window.MODULES=[{"id": "01", "slug": "intro", "title": "Introduction to the Defender RMF", "tagline": "Where the Defender comes from, sand versus RMF, and what actually does the filtering", "scenes": [{"dur": 12, "shot": "sp55:orbit", "layout": "center", "h": "Introduction to the Defender RMF", "p": ["This module covers where the Defender comes from, how high-rate sand compares to regenerative media filtration, and what is actually doing the filtering inside the tank."]}, {"dur": 18, "shot": "sp55:orbit", "layout": "left", "h": "Neptune Benson, since 1956", "p": ["Neptune Benson started in 1956. We launched the first Defender RMF in 2003, the Micron One, and that unit is still running today.", "ETS UV and Boston Aquatics came in 2011, Evoqua acquired us in 2016, and Xylem in 2022. That is why you see a few different brands across our documents."]}, {"dur": 18, "shot": "sp55:orbit", "layout": "right", "h": "Three sites, three jobs", "p": ["You are training with us in Warwick, Rhode Island, where engineering and tech support live. If you call in for help, you are probably talking to me or Dallas.", "Thomasville, Georgia fabricates the Defender and our large steel tanks. Holland, Michigan assembles, kits, and ships almost everything Xylem sends out in the U.S."]}, {"dur": 22, "shot": "sp55:section", "layout": "left", "h": "Welded, ground, painted, lined", "p": ["Each tank is carbon steel. The lid, ring, and shell are paired from the first weld to the last bolt so they fit as a set.", "Seams are welded slowly and ground smooth, then the tank is painted outside and lined inside with a two-part coating. That lining keeps pool water off the steel.", "Every unit leaving Thomasville has a build report: torque values, lining, and any minor defect worth telling the customer about."], "stats": [{"n": 5000, "suffix": "+", "label": "Defenders installed worldwide"}, {"n": 500, "suffix": "", "label": "Shipped last year"}]}, {"dur": 20, "shot": "card", "layout": "left", "h": "High-rate sand is depth filtration", "p": ["A sand filter cleans by depth. Water comes in through the top manifold, down through the bed, and out the laterals. The deeper the bed, the cleaner the water, down to about 30 microns.", "To clean it you backwash: reverse the flow, fluidize the bed, and send the dirt to waste. That is water, heat, and chemicals down the drain, plus downtime."]}, {"dur": 20, "shot": "card", "layout": "left", "h": "Backwash takes more water than people think", "p": ["The glass-tank video shows it. At 15 gpm per square foot the bed barely moves. You need 18 to 20 gpm per square foot to really get sand clean.", "Plenty of facilities backwash low to save water, and the bed stays dirty. Backwash high and you throw away a lot more water and chemical. There is no free option with sand."], "stats": [{"n": 15, "suffix": " gpm/ft²", "label": "Barely fluidizes the bed"}, {"n": 20, "suffix": " gpm/ft²", "label": "What it takes to get sand clean"}]}, {"dur": 22, "shot": "card", "layout": "center", "h": "Sand versus Defender RMF", "p": ["Two horizontal sand filters and one SP-33 handle about the same flow. In a filter room where space is at a premium, that footprint difference matters."], "table": {"head": ["", "High-rate sand", "Defender RMF"], "rows": [["Filtration", "Depth, through a sand bed", "Surface, through a perlite cake"], ["Removes down to", "About 30 micron", "About 1 micron"], ["Cleaning", "Backwash to waste", "Bump and precoat, nothing to waste"], ["Cost of cleaning", "Water, heat, chemicals, downtime", "Minimal between media changes"], ["Footprint", "Two horizontal tanks", "One SP-33 for the same flow"]]}}, {"dur": 16, "shot": "card", "layout": "left", "h": "The published numbers against sand", "p": ["Side-by-side photos from the same pool, taken about 15 ft away, show it. A freshly cleaned sand filter still leaves the water cloudy next to a Defender pool."], "stats": [{"n": 90, "suffix": "%", "label": "Water savings, up to"}, {"n": 50, "suffix": "%", "label": "Energy savings"}, {"n": 30, "suffix": "%", "label": "Chemical savings"}, {"n": 95, "suffix": "%", "label": "Less particulate"}]}, {"dur": 20, "shot": "sp55:tubes", "layout": "left", "h": "Hundreds to thousands of tube elements", "p": ["Each tube element is a spiral stainless steel spring core with a woven mesh sleeve. They hang from the tube sheet, hundreds to thousands of them depending on the model.", "Each tube gives you 0.78 ft² of surface. An SP-55 carries 2,076 tubes, 1,625 ft² of filter area. Even an SP-33 has about the floor area of a two-bedroom apartment."], "stats": [{"n": 0.78, "suffix": " ft²", "label": "Per tube element"}, {"n": 2076, "suffix": "", "label": "Tubes in an SP-55"}, {"n": 1625, "suffix": " ft²", "label": "SP-55 filter area"}]}, {"dur": 24, "shot": "sp55:filter", "layout": "right", "h": "The perlite is the filter", "p": ["Perlite is finely ground volcanic glass, porous, with a huge amount of surface area. It coats the tubes and forms the cake. The tubes are only the framework it sticks to.", "Water passes through the cake, contaminants stay in the perlite, and clean water enters the tube and leaves through the top of the tank.", "That cake stops particles down to about 1 micron: pollen, smoke, white and red blood cells, and a lot of bacteria. None of it goes back to the pool."]}, {"dur": 16, "shot": "sp55:window", "layout": "left", "h": "Watch the differential, not the clock", "p": ["A clean cake runs about 1 to 3 psi differential. As it loads, the differential climbs. You see it on the gauges or on the RMF12 screen.", "Once a day, or at about 10 psi, the media needs regenerating. That is a bump and a precoat, not a backwash. No water goes to waste."]}, {"dur": 20, "shot": "sp55:bump", "layout": "bottom", "h": "Bumping: shake it off", "p": ["The pump stops, the valves close, and the bump tire on the head vents. The weight of the tube sheet drops it, then the tire reinflates and lifts it. Ten times.", "All the perlite shakes loose into suspension in the tank, still holding the dirt it caught."]}, {"dur": 14, "shot": "sp55:precoat", "layout": "bottom", "h": "Precoat: lay it back down", "p": ["The pump restarts at jog speed and water loops through the precoat line. Perlite follows the path of least resistance and re-coats the tubes with a fresh face outward.", "It works a lot like activated carbon. Bumping does not make the perlite clean, it reorients it. It may still be 10% dirty, and that is why media lasts weeks, not forever."]}, {"dur": 18, "shot": "card", "layout": "left", "h": "When bumping stops working, change media", "p": ["After a bump you should drop back to 1 to 3 psi, maybe 5 or 6. When a bump no longer gets you under 10 psi, the perlite is spent.", "Then you bump, drain, wash the tubes, and vacuum in fresh perlite. Plan on 4 to 6 weeks of media life on a correctly sized system."]}, {"dur": 16, "shot": "sp55:orbit", "layout": "right", "h": "Where Defenders run", "p": ["Indoor and outdoor water parks in the UK, lazy rivers, wave pools, slide complexes, competition pools. Outdoor water carries a lot more sunscreen and body oil, and the Defender keeps it clear.", "The competition pools at the Olympic trials ran on Defenders. The swimmers notice: less in the water, a little faster through it."]}, {"dur": 16, "shot": "card", "layout": "center", "h": "Three things to remember", "p": ["The perlite is the filter. The tubes are only the framework it sticks to.", "Sand backwashes water, heat, and chemicals to waste to get to 30 microns. The Defender bumps and precoats to 1 micron with nothing to waste.", "Bumping reorients the perlite, it does not clean it. When a bump no longer brings the differential under 10 psi, change the media."]}], "quiz": [{"q": "Inside a Defender, what actually captures the contaminants?", "options": ["The woven mesh sleeve on each tube", "The perlite cake coating the tubes", "The stainless spring core", "The felt gasket at the tube sheet"], "answer": 1, "why": "The perlite is the filter. The tube elements are only the framework it adheres to."}, {"q": "Roughly what particle size does a Defender remove, compared with high-rate sand?", "options": ["30 micron, same as sand", "10 micron versus 30 micron for sand", "1 micron versus about 30 micron for sand", "0.1 micron versus 1 micron for sand"], "answer": 2, "why": "Surface filtration through the perlite cake gets down to about 1 micron, while a sand bed stops at about 30."}, {"q": "In the glass-tank video, what backwash rate was needed to properly fluidize and clean the sand bed?", "options": ["5 to 8 gpm per square foot", "10 to 12 gpm per square foot", "15 gpm per square foot", "18 to 20 gpm per square foot"], "answer": 3, "why": "At 15 gpm per square foot the bed barely moved. It took 18 to 20 to really clean it, which means more water and chemical to waste."}, {"q": "What does a bump cycle do to the perlite?", "options": ["Washes it clean so it can be reused indefinitely", "Shakes it off the tubes so a fresher face is re-laid during precoat", "Sends it to the drain", "Compresses it tighter onto the tubes"], "answer": 1, "why": "Bumping reorients the perlite rather than cleaning it, which is why media lasts weeks and eventually needs changing."}, {"q": "Which Neptune Benson site fabricates the Defender tanks?", "options": ["Warwick, Rhode Island", "Holland, Michigan", "Thomasville, Georgia", "Zeeland, Michigan"], "answer": 2, "why": "Thomasville welds, lines, and assembles the Defender. Holland kits and ships, and Warwick is engineering, support, and training."}]}, {"id": "02", "slug": "modes", "title": "Operating Modes and Key Parameters", "tagline": "Idle, precoat, filter, bump, the numbers that matter, perlite, and reading the nameplate", "scenes": [{"dur": 12, "shot": "rmf12:closed", "layout": "center", "h": "Operating Modes and Key Parameters", "p": ["This module covers the four operating modes, how bump and precoat actually work, the pressures and rates you run to, the perlite itself, and how to read a model number and nameplate."]}, {"dur": 24, "shot": "rmf12:closed", "layout": "center", "h": "Always in one of four modes", "p": ["The Defender is always idle, precoating, filtering, or bumping. The top left of the RMF12 screen shows the mode, each valve, the pump, and time remaining. Top right is the differential."], "table": {"head": ["Mode", "Pump", "Effluent valve", "Precoat valve", "Bump tire"], "rows": [["Idle", "Off", "Closed", "Closed", "Inflated"], ["Precoat", "On, jog speed", "Closed", "Open", "Inflated"], ["Filter", "On, set point", "Open", "Closed", "Inflated"], ["Bump", "Off", "Closed", "Closed", "Cycling"]]}}, {"dur": 28, "shot": "anim:defender-install-filter-mode", "layout": "left", "h": "Idle and filter mode", "p": ["Idle means the pump is off, both pneumatic valves are closed, the tire is inflated, and nothing flows.", "Filter is normal operation: pump at set point, effluent valve open, precoat valve closed, clean water back to the pool. Through the window the tubes should look evenly coated."]}, {"dur": 22, "shot": "card", "layout": "bottom", "h": "Filter mode: effluent open, precoat closed", "p": ["In filter mode the pump runs at set point, the effluent valve is open and the precoat valve is closed. Clean water goes back to the pool through the flow meter and the treatment loop.", "Right after a fresh precoat the differential should read about 1 to 3 psi. That is your clean baseline for the rest of the week."]}, {"dur": 28, "shot": "anim:defender-sp55-bump-cycle", "layout": "bottom", "h": "Bump mechanics: 90 psi, ten times", "p": ["The bump tire on the head holds about 90 psi. The quick exhaust valve dumps the air, the tire deflates, and the weight of the tube sheet drops it. Then it reinflates and lifts.", "Standard cycle is 10 bumps. Twenty or thirty will not hurt anything, but it adds O-ring wear and compressor run time. One compressor on three filters: keep each at 10."]}, {"dur": 20, "shot": "card", "layout": "bottom", "h": "Three ways a bump gets started", "p": ["Manually from the RMF12 screen. Put it behind the password so random people do not start one.", "On a schedule, say 2 a.m. daily when the pool is empty. Or automatically at 12 psi differential, the factory default. You can adjust it, but 12 is where we like it.", "Bump daily as a habit, and always bump once more right after a media change to even out the coat."]}, {"dur": 34, "shot": "anim:defender-install-precoat", "layout": "bottom", "h": "Precoat: jog speed and the sight glass", "p": ["The pump restarts at a reduced jog speed. Water loops through the precoat line, and the perlite re-coats the tubes.", "Watch the precoat sight glass. When the water clears, precoat is done. Every start goes through a bump and a 10-minute precoat before filter mode."]}, {"dur": 22, "shot": "card", "layout": "bottom", "h": "Ten minutes, usually less, never twenty", "p": ["New systems often clear in 5 or 6 minutes. We still set 10 so all the perlite gets through. Older systems or low precoat flow may need longer.", "If you are past 20 minutes, something needs adjusting: precoat hertz, media quantity, or flow. Call us before you push the timer higher.", "When precoat ends, the effluent valve opens and the precoat valve closes about 5 seconds later to avoid water hammer. You may see water in the precoat line briefly."]}, {"dur": 22, "shot": "sp55:tubes", "layout": "left", "h": "Precoat at 35 to 45 Hz", "p": ["If filter mode runs at 55 to 60 Hz, precoat should run at 35 to 45 Hz. Slower and longer beats fast and hard.", "One of you lived this: a 4,400 gpm filter with a 75 hp pump and no speed reduction. It pushed tubes in on themselves, and somebody had to visit monthly to throttle it by hand.", "Over-pumping precoat drives perlite through the mesh, damages tube elements, and sends media back to the pool. Nobody is happy with that call."], "stats": [{"n": 35, "suffix": " to 45 Hz", "label": "Precoat speed"}, {"n": 55, "suffix": " to 60 Hz", "label": "Typical filter mode"}]}, {"dur": 12, "shot": "sp55:window", "layout": "right", "h": "Patchy coat after a media change", "p": ["If the coat looks uneven after a media change, bump and precoat a second time before you put it back in service. If it looks good the first time, leave it alone."]}, {"dur": 26, "shot": "card", "layout": "center", "h": "Key operating parameters", "p": ["Slower is better on filtration rate. Lazy rivers and wave pools sit at the low end. Competition pools and slide complexes can run higher."], "table": {"head": ["Parameter", "Value"], "rows": [["Design filtration rate", "0.5 to 1.4 gpm/ft²"], ["Clean differential", "About 1 to 3 psi"], ["Bump", "Daily, or at about 10 psi"], ["Auto bump", "12 psi, factory default"], ["Alarm and auto shutdown", "15 psi"], ["Inspect internals", "Sustained 25 psi and above"], ["Media change", "10+ psi right after a bump, or visibly fouled"]]}}, {"dur": 22, "shot": "sp55:tubesheet", "layout": "left", "h": "Sustained 25 psi and above damages internals", "p": ["Fifteen psi is a safety setting. Going to 16 does not break anything. At 25 and above, tube elements can be crushed and small parts stop moving freely.", "We pulled the logs on one site running 30 to 50 psi for close to a year. Tubes were damaged and welds on the tube sheet were being ripped apart. The alarms are there for a reason.", "On older controllers, if a bump does not clear the differential, the system loops back into precoat over and over. That is it telling you to change media."]}, {"dur": 26, "shot": "sp55:mediachange", "layout": "bottom", "h": "Use Harborlite 700", "p": ["The tube mesh weave is matched to Harborlite 700. Finer grades pass through the mesh and reach the pool. Coarser or wider-range grades give you less clear water.", "It comes in 25 lb bags, sometimes 45 or 50. The required amount is on the nameplate and the decal. More is fine, less is not, so round up to the next full bag.", "Seventy-five pounds required means three 25 lb bags. Too little leaves bare tube, so tubes coat with grease and dirt and water bypasses the media."]}, {"dur": 16, "shot": "sp55:tubes", "layout": "left", "h": "Too much perlite bridges. Do not panic.", "p": ["Overload and perlite bridges between tubes. Some bridging is fine, it can even improve clarity, but that area loads faster.", "Perlite stuck on the tank wall or window after precoat is harmless. Hose it out at the next service. And no, do not put the whole pallet in."]}, {"dur": 20, "shot": "card", "layout": "left", "h": "Media life, disposal, and dust", "p": ["Plan on 4 to 6 weeks. Consistently under 3 weeks means check sizing, flow rate, strainer, and media grade. Send us the controller logs and we will run a report.", "Perlite is inert, but local health codes vary. DE screens and separation tanks are available where a drain discharge is not allowed.", "Perlite dust is not hazardous, but glasses and a mask are good practice. With DE, always wear a mask."]}, {"dur": 16, "shot": "card", "layout": "left", "h": "NSF 50 changed the math, not the flow", "p": ["The old standard counted tube diameter plus the perlite cake as surface area. The new one counts the tube element only, and raised the allowable rate per square foot to compensate.", "Published surface areas changed. The flow each model handles did not. We still design at 0.5 to 1.4 gpm per square foot."]}, {"dur": 20, "shot": "sp55:orbit", "layout": "right", "h": "Reading the model number", "p": ["SP-49-48-1548: SP is Defender, 49 in tank diameter, 48 in tube length, 1,548 tubes. Diameters run 27, 33, 41, 49, and 55.", "Tube length is standardized at 48 in now. Units 10 years or older may have 36, 38, or 42 in tubes. The last number is the maximum tube count, which is what you use when ordering replacements."]}, {"dur": 18, "shot": "sp55:orbit", "layout": "left", "h": "The nameplate and the serial number", "p": ["The stainless pad shows model, serial number, manufacture date, filter area, design filtration rate in gpm per square foot, flow rate in gpm, max working pressure, and media requirement in pounds.", "The decal sheet sits opposite the controller with operating steps and project data. Give us the serial number and we pull the original project, design flow, motor, O&M, ship date, and warranty status."]}, {"dur": 22, "shot": "card", "layout": "center", "h": "Five product lines", "p": ["The FP used a pump-driven bump on pressure differential instead of a tire. Once we cut the height requirement on the standard tank, we went back to the traditional design."], "table": {"head": ["Line", "Use"], "rows": [["Standard", "Most installations"], ["Reduced Height", "Filter rooms with low ceilings"], ["Assero", "Lower flow, roughly 100 to 500 gpm. Smallest is the Assero 250"], ["Virtuo", "Released in the last year. Pairs with reduced height: more flow at larger diameter in a shorter package"], ["FP (older)", "Pump-driven bump, no tire. No longer built"]]}}, {"dur": 18, "shot": "sp55:orbit", "layout": "right", "h": "Sizing reference by model", "p": ["The SP-33 covers roughly 286 to 800 gpm. The 41 and 49 are the most common. Past that we usually stack units.", "The SP-55 is the largest, up to roughly 1,500 to 2,000 gpm. Confirm sizing with your sales director. Dimensions, connections, and bracket positions are on each spec sheet, the O&M, and the website."]}, {"dur": 16, "shot": "card", "layout": "center", "h": "Three things to remember", "p": ["Bump at about 10 psi, auto bump at 12, alarm at 15, and inspect the internals if it sits at 25 or more.", "Precoat runs 10 minutes at 35 to 45 Hz. If it takes more than 20 minutes, call us instead of pushing the pump harder.", "Harborlite 700 only, the amount on the nameplate rounded up to the next bag. More is fine, less is not."]}], "quiz": [{"q": "Filter mode runs at 58 Hz. Where should the precoat jog speed be set?", "options": ["58 Hz, same as filter mode", "50 to 55 Hz", "35 to 45 Hz", "As low as the VFD will go"], "answer": 2, "why": "Precoat should run at 35 to 45 Hz when filter mode runs 55 to 60 Hz, so perlite is not driven through the tubes or into the pool."}, {"q": "At what differential does the RMF12 start a bump automatically, by factory default?", "options": ["5 psi", "10 psi", "12 psi", "15 psi"], "answer": 2, "why": "Auto bump is 12 psi by default. Ten is when you should think about bumping, and 15 is the alarm and shutdown point."}, {"q": "The nameplate says 75 lb of media. You have 25 lb bags. What do you load?", "options": ["Two bags, to leave room for bridging", "Two and a half bags, measured out", "Three bags", "The whole pallet, more is better"], "answer": 2, "why": "Round up to the next full bag. More is fine, less is not, and a whole pallet is not the answer either."}, {"q": "A precoat on an older system is still cloudy at 22 minutes. What should you do?", "options": ["Raise the precoat timer to 30 minutes", "Raise the pump to full filter speed to finish faster", "Call support, since something needs adjusting", "Drain and change the media immediately"], "answer": 2, "why": "Over 20 minutes means something needs adjusting: precoat hertz, media quantity, or flow. Call before you push the timer or the pump."}, {"q": "A Defender's nameplate reads SP-49-48-1548. What does 1548 tell you?", "options": ["The design flow rate in gpm", "The filter area in square feet", "The maximum number of tube elements", "The serial number"], "answer": 2, "why": "The last number is the maximum tube count, which is the number you use when ordering replacement tubes."}, {"q": "Why Harborlite 700 and not a finer perlite grade?", "options": ["Finer grades cost more", "The tube mesh weave is matched to 700, and finer grades pass through to the pool", "Finer grades will not vacuum into the tank", "Finer grades clog the precoat sight glass"], "answer": 1, "why": "The mesh is matched to Harborlite 700. Finer grades bypass the tubes, and coarser or wider-range grades give less clear water."}]}, {"id": "03", "slug": "installation", "title": "Design, Storage and Installation", "tagline": "Flow path, piping rules, pump layouts, clearances, what is in the crate, and how to move the tank", "scenes": [{"dur": 12, "shot": "install:overview", "layout": "center", "h": "Design, Storage and Installation", "p": ["This module walks the installation front to back: the flow path and every component on it, piping and pump rules, clearances, what ships in the crate, and how to store and handle the tank."]}, {"dur": 20, "shot": "install:overview", "layout": "left", "h": "The flow path, pool to pool", "p": ["Pool, check valve, hair and lint strainer, precoat tee, pump, and into the bottom of the filter. Through the perlite and tubes, out the top, through the effluent valve and flow meter.", "Then disinfection and treatment: the UV loop, heater, and chemical feed, and back to the pool."]}, {"dur": 16, "shot": "install:marks F28,F29,F30", "layout": "left", "h": "Check valve and strainer", "p": ["The check valve on the influent keeps water from draining back to the pool when the system is off. Older RMF8 systems used a pneumatic influent valve instead.", "The strainer catches band-aids, twigs, and leaves before the pump. One strainer can feed two pumps off a tee."]}, {"dur": 18, "shot": "install:marks F31,F32,F33,D6", "layout": "right", "h": "Three feet straight into the influent", "p": ["After the pump, give the influent about 3 ft of straight horizontal pipe from the last elbow into the connection. A valve in that run is fine.", "Twenty-eight inches or 40 in will not make much difference. What we are avoiding is an elbow right at the inlet adding turbulence inside the tank."]}, {"dur": 16, "shot": "install:marks D7,F37", "layout": "left", "h": "Flow meter after the effluent valve", "p": ["The effluent valve sits on the return line. The flow meter belongs after it, so it is not caught in the precoat loop and confusing the VFD.", "Our demo skid has the meter somewhere else for convenience. Do not copy the demo skid."]}, {"dur": 18, "shot": "install:group uvloop", "layout": "right", "h": "The UV loop and the heater bypass", "p": ["A bypass loop can route some or all of the flow through the UV chamber. A partially closed valve on the main return adds back pressure to push water through the loop.", "Fully open is fine if you do not need it. A heater bypass typically follows the UV loop, and chemicals come after everything."]}, {"dur": 18, "shot": "install:group effluent", "layout": "left", "h": "Chemicals go after the filter", "p": ["Chlorine and acid are dosed after the filter, after everything, so we are not injecting straight into the Defender.", "The chemical controller sample point is usually on filtered water so you see what is returning to the pool. It varies by controller and chemical, so confirm with the controller manufacturer."]}, {"dur": 16, "shot": "install:group vent", "layout": "right", "h": "Two manual vents minimum", "p": ["One at the high point of the precoat loop, one on top of the tank or the effluent. Tap as many high points as you can.", "Know where they are on every site. They are manual, and new operators need to open them to purge air at startup and during a media change."]}, {"dur": 12, "shot": "install:marks D4,D5", "layout": "left", "h": "Window and gauges", "p": ["The viewing window shows precoat quality. The gauges show influent and effluent pressure, teed into the same taps as the electronic transducers. They are your analog backup."]}, {"dur": 18, "shot": "install:overview", "layout": "left", "h": "Horizontal and vertical. Nothing across moving parts.", "p": ["Run piping horizontal and vertical. Pitched runs can work, but they get complicated fast.", "Do not pipe across anything that moves. A vent line installed so the head cannot lift is a common tech support call. Use unions so lines come apart for service."]}, {"dur": 18, "shot": "install:group precoat", "layout": "right", "h": "Precoat line: two pipe sizes smaller", "p": ["Rule of thumb: the precoat line is two pipe sizes smaller than the influent and effluent. We help size it when we quote the system.", "The precoat valve, the sight glass, and the precoat vent all live on this loop. Everything you need to watch a precoat is right here."]}, {"dur": 20, "shot": "install:marks F33,F29", "layout": "left", "h": "Avoid one pump feeding two filters", "p": ["One pump per filter is standard. Two pumps per filter is fine, duty and standby or running together. We have instructions for both on VFDs and motor starters.", "One pump feeding two Defenders is the one we do not like. Balancing precoat between two tanks on one loop is very hard. If the next size up does not fit, use two smaller units."]}, {"dur": 16, "shot": "install:overview", "layout": "right", "h": "One Defender per body of water", "p": ["We prefer a Defender per pool or application so flow can be tuned to the load. The beach entry with the play toys wants one rate, the lazy river wants a slower one.", "Two units can share one compressor. Link the controllers so they do not bump at the same time."]}, {"dur": 20, "shot": "install:marks D3,D1", "layout": "left", "h": "Room for the head to swing", "p": ["Leave room for the head to swing a full 360° on the davit. Mirror davits are available for side-by-side units, so two heads swing in opposite directions.", "Leave about 16 in above the tank. The bump assembly rises with the head, and that clearance lets you lift and swing without removing it."], "stats": [{"n": 16, "suffix": " in", "label": "Head clearance above the tank"}, {"n": 360, "suffix": "°", "label": "Davit swing"}]}, {"dur": 18, "shot": "install:marks D10", "layout": "right", "h": "Tank drain and TDS drain", "p": ["The drain outlet can be oriented in 90° increments. An automatic pneumatic drain is optional. I would love it as standard, but it is one more thing to go wrong.", "For high-TDS or semi-saltwater pools, an automatic precoat-loop drain purges water, since the Defender never dumps water the way a backwash does."]}, {"dur": 20, "shot": "install:overview", "layout": "left", "h": "Flanged tanks, outdoor installs, and ladders", "p": ["Flanged split tanks are available when the room is tight. Flanged, mirror davit, or any custom build has a longer lead time. Standard units are stocked.", "Outdoor installs are fine. The controller is NEMA 4 or 12, but cover it if you can. And think about service: a UV you need a ladder to reach gets serviced less."]}, {"dur": 22, "shot": "install:marks D12,D14,D20,D21,D13", "layout": "right", "h": "Check the crate on arrival", "p": ["RMF12 controller, valve kit, vacuum transfer unit, plumbing kit, gauge panel kit, drain valve assembly, compressor, ChemClean Express if ordered, Defender toolkit, 200 to 500 ft of poly tubing, and a water separator.", "The toolkit is a U-bracket with a bearing and all-thread for lowering the tube sheet. It goes missing on site constantly. Call for a replacement, or we will tell you how to build one."]}, {"dur": 12, "shot": "install:marks D6,D7,D8,D11", "layout": "left", "h": "The valve kit", "p": ["Influent check valve, pneumatic effluent butterfly valve, pneumatic precoat valve, and precoat sight glass. Sizes read influent, effluent, precoat, so 6-4-3 means a 3 in precoat line."]}, {"dur": 22, "shot": "sp55:orbit", "layout": "left", "h": "Storage: dry matters more than cold", "p": ["Tanks ship shrink-wrapped and can sit outdoors, though a crate or cover is better. Units sometimes wait 2 to 3 years for startup. Storage range is -25 to 120 °F.", "Shrink wrap is not waterproof, so store perlite dry and keep the accessory crate dry. Cold is fine. Water that gets in and freezes does the damage, and humidity kills more than temperature.", "Warranty starts at ship date. After long storage, run the startup checklist and call us about anything that got damaged."]}, {"dur": 20, "shot": "sp55:head", "layout": "right", "h": "Keep the bump tire inflated when you move it", "p": ["It ships at about 90 psi, and 50 psi is still OK. A deflated tire lets the tube sheet swing on the lift shaft and bend it.", "A bent lift shaft is the number one cause of rough bumping on new startups. To reinflate, remove the quick exhaust valve and add air through the isolation ball valve.", "Use the lifting lugs to crane the unit into place. We have seen a flying Defender or two, and every install is a unique story."]}, {"dur": 16, "shot": "card", "layout": "center", "h": "Three things to remember", "p": ["Horizontal and vertical piping, nothing across moving parts, unions where lines must come apart, and 3 ft straight into the influent.", "One pump per filter and one Defender per body of water. Never one pump feeding two filters.", "Keep the bump tire inflated when you move the tank, store it dry, and check the crate for the toolkit the day it arrives."]}], "quiz": [{"q": "Where does the flow meter belong on a Defender installation?", "options": ["On the influent line before the pump", "On the precoat line next to the sight glass", "On the effluent line after the effluent valve", "Anywhere, since the PID loop corrects for it"], "answer": 2, "why": "After the effluent valve keeps the meter out of the precoat loop, so the VFD only sees filter-mode flow."}, {"q": "Which pump configuration should you avoid?", "options": ["One pump per filter", "Two pumps per filter in duty and standby", "Two pumps per filter running together", "One pump feeding two filters"], "answer": 3, "why": "Balancing precoat between two tanks on one loop is very hard. Use two smaller units with their own pumps instead."}, {"q": "How much clearance should you leave above the tank, and why?", "options": ["6 in, for the vent line", "16 in, so the head and bump assembly can lift and swing", "36 in, for the vacuum hose", "None, the head swings sideways"], "answer": 1, "why": "About 16 in lets the head lift and swing on the davit without removing the bump assembly."}, {"q": "A tank has to go down a stairwell on its side. What do you check first?", "options": ["That the legs are collapsed", "That the tank drain is open", "That the bump tire is inflated", "That the window cover is removed"], "answer": 2, "why": "A deflated tire lets the tube sheet swing and bend the lift shaft, the number one cause of rough bumping on new startups."}, {"q": "A valve kit is listed as 6-4-3. What is the 3?", "options": ["The number of pneumatic valves", "The effluent valve size in inches", "The precoat line size in inches", "The check valve pressure class"], "answer": 2, "why": "Kit sizes read influent, effluent, precoat. A 6-4-3 kit has a 3 in precoat valve and sight glass."}, {"q": "A unit sat on site for two winters before startup. What matters most for it to survive storage?", "options": ["Keeping it above freezing at all times", "Keeping it dry so trapped water cannot freeze", "Leaving the shrink wrap off for airflow", "Deflating the bump tire to relieve stress"], "answer": 1, "why": "Cold within the storage range is fine. Water that gets in and freezes, and humidity, are what cause damage."}]}, {"id": "04", "slug": "components", "title": "Defender Filter Components", "tagline": "Head to legs, the bump assembly and its O-rings, the tube sheet stack, lining, gauges, and the vacuum unit", "scenes": [{"dur": 12, "shot": "sp55:section", "layout": "center", "h": "Defender Filter Components", "p": ["This module takes the filter apart piece by piece: the head and window, the diffuser, the tube sheet, the bump assembly and the O-rings that keep pool water away from air, the lining, and the vacuum transfer unit."]}, {"dur": 16, "shot": "sp55:head", "layout": "left", "h": "The filter head", "p": ["The head unbolts and lifts on the davit with a bottle jack, then swings 360°. That is how you get inside for service.", "On an SP-55 the far side of the head tilts down when lifted. The davit still carries the whole weight, just be aware of it."]}, {"dur": 14, "shot": "sp55:head", "layout": "right", "h": "Effluent connection and controller mount", "p": ["The effluent connection bolts to the top of the head. Pulling it is the quickest way to look at the top of the tube sheet.", "The controller mount can go on different sides of the tank for custom layouts. The decal sheet usually sits opposite the controller."]}, {"dur": 16, "shot": "sp55:window", "layout": "left", "h": "Viewing window: 6 in or 4 in", "p": ["Current units have a 6 in acrylic window. Older FP and Assero units have a 4 in window, which is tight for tube washing but workable.", "The cover is carbon steel and heavy. A lighter fiberglass version, and a hinged one, are coming. Leave one or two bottom bolts in when you reassemble."]}, {"dur": 18, "shot": "sp55:bottom", "layout": "right", "h": "Three generations of diffuser", "p": ["Current units use a Y diffuser on the influent to settle the incoming flow. Older units have a T diffuser, which is fine. The Y is just easier to build.", "The oldest have a circular downcomer with slats. We only supply 48 in replacement tubes now, and 48 in tubes can catch on those slats. Check before you order."]}, {"dur": 14, "shot": "sp55:bottom", "layout": "left", "h": "Tank drain and legs", "p": ["The drain sits at the bottom of the tank with a handle extension. An automatic pneumatic version is available. Sediment settles there, so a slow drain usually means buildup.", "Legs ship collapsed for transport and adjust up to whatever install height works for your room."]}, {"dur": 16, "shot": "sp55:tubesheet", "layout": "right", "h": "Tube sheet assembly", "p": ["A laminated 316 stainless plate hanging from the lift shaft. The 27 and 33 use a flat plate. From the 41 up we add stiffener plates to keep it level.", "The tubes are not bolted in. They hang through the sheet and are sandwiched in place by the hold-down plate."]}, {"dur": 14, "shot": "sp55:head", "layout": "left", "h": "Davit and bottle jack", "p": ["The bottle jack ships greased. If the unit sat for years, check it before you lean on it. Newer models have guides so the head rises straight.", "It is a standard bottle jack. If yours fails, a bigger one from the hardware store will do the job."]}, {"dur": 20, "shot": "sp55:head", "layout": "right", "h": "The bump assembly, unchanged since 2003", "p": ["Lift shaft top nut, isolation valve where the quick exhaust connects, top nut, top plate, bump tire, and housing. It is sold as a complete kit.", "The design has not changed since 2003, so replacement is like-for-like on any unit. Remove the heavy top nut and the lift shaft is free floating, which is why the toolkit exists."]}, {"dur": 24, "shot": "sp55:tubesheet", "layout": "left", "h": "Two O-rings between pool water and air", "p": ["Under the tire the lift shaft runs through a Delrin bump bushing held by a snap ring, with O-rings on the bushing and the shaft. Those O-rings separate the water side of the tank from the air side.", "Water or rust at the quick exhaust, or a muffler turning brown or black, means the seal is going. Replace the O-rings before you put it back in service.", "Plan on them at 5 years. Some units need them at 3, others go to 10. Weak or incomplete bumps usually trace back here."]}, {"dur": 16, "shot": "sp55:head", "layout": "right", "h": "A clogged muffler stops the bump", "p": ["The small white threaded piece on the quick exhaust only quiets the bump. If it clogs with water or grime, the tire cannot deflate.", "Unscrew it and keep running, louder, and replace it later. And never plumb air straight into the tire with no quick exhaust. That tire will never deflate."]}, {"dur": 16, "shot": "sp55:head", "layout": "left", "h": "Twelve years, no service, seized bushing", "p": ["A unit at Legoland ran about 12 years without any maintenance. Impressive, but the Delrin bump bushing had seized in the assembly.", "They had to drill into it and chip it out. Regular lubrication on the O-rings and bushing is what keeps you from doing that job."]}, {"dur": 18, "shot": "sp55:tubesheet", "layout": "right", "h": "The stack: sheet, felt, tubes, hold-down plate", "p": ["Tube sheet first, then the felt gasket, then every tube dropped through, then the hold-down plate, then about 15 bolts torqued to 30 ft-lbs.", "Assemble it in that order. Out of order it still runs, but the felt will not seal and you get media bypass."], "stats": [{"n": 15, "suffix": "", "label": "Bolts, about"}, {"n": 30, "suffix": " ft-lbs", "label": "Hold-down plate torque"}]}, {"dur": 20, "shot": "sp55:tubesheet", "layout": "left", "h": "Media to the pool: check the felt first", "p": ["The felt seals each tube and the sheet edge. With the tire inflated the outer felt ring presses against a lip in the head, sealing all but about 1 to 2% of flow.", "Felt, not rubber, because rubber is attacked by chemicals. High chlorine or temperature degrades felt too. Look for an indent in the outer ring: no indent, no seal."]}, {"dur": 14, "shot": "sp55:tubesheet", "layout": "right", "h": "Go easy on tube sheet bolts", "p": ["Lubricant, a little heat, and low torque to start. I have seen people strip one bolt, learn nothing, and strip five more.", "A stripped bolt gets drilled out, or the tube sheet gets replaced. Neither one is a good day."]}, {"dur": 14, "shot": "sp55:tubewash", "layout": "bottom", "h": "Rotating the sheet is also an O-ring check", "p": ["With the tire deflated, the tube sheet rotates so you can reach every tube during a wash. Turn it in the direction on the unit's sticker. The wrong way wears the lift shaft O-rings.", "It should turn with little resistance. Hard to turn means the O-rings are dry or torn."]}, {"dur": 20, "shot": "sp55:section", "layout": "left", "h": "Flexcel 3000 lining", "p": ["The two-part Flexcel 3000 lining keeps pool water off the carbon steel. Warranted 10 years, and I have seen tanks go 20 plus on the original.", "It chips like powder coat if you hit it. Watch the head flange and the window opening, where people bang the cover or the hose. Quart repair kits include rust inhibitor."]}, {"dur": 16, "shot": "install:marks D5", "layout": "right", "h": "Flush the gauge tees", "p": ["The analog gauges tee into the same taps as the electronic transducers, so both should read the same.", "Perlite builds up in those lines. One outdoor site grew algae in them. Weird pressure readings: disconnect the tees, flush, and reconnect."]}, {"dur": 22, "shot": "install:marks D14,D15,D16,D17,D18,D19", "layout": "left", "h": "Vacuum transfer unit", "p": ["Mounted on the tank, wired into the junction box on the side, controlled by the RMF12. It runs on 120 V, with other voltages for Europe and Canada.", "Some ship with a plug. Cut it off and land the leads in the junction box. Brands vary since the COVID supply problems, specs held as close as possible.", "No vacuum at the hose: check the junction box wiring, and make sure every other valve is closed so the tank can pull vacuum."]}, {"dur": 16, "shot": "card", "layout": "center", "h": "Three things to remember", "p": ["The O-rings on the lift shaft and bump bushing are the only thing between pool water and the air side. Rust at the quick exhaust means replace them.", "Media back to the pool: check the felt gasket first, and look for the indent on the outer ring.", "Go easy on tube sheet bolts, keep the O-rings lubricated, and flush the gauge tees when a reading looks wrong."]}], "quiz": [{"q": "Perlite is showing up in the pool. What do you check first?", "options": ["The precoat valve needle valves", "The felt gasket at the tube sheet", "The quick exhaust muffler", "The flow meter jumper"], "answer": 1, "why": "The felt gasket seals each tube and the sheet edge. It is consumed over time, so it is the first stop for media bypass."}, {"q": "The muffler on the quick exhaust has turned brown and there is moisture at it. What does that tell you?", "options": ["The compressor is over-pressurized", "The lift shaft or bushing O-rings are leaking and need replacing", "The tire pressure is too low", "Normal wear, nothing to do"], "answer": 1, "why": "Those O-rings separate the water side from the air side. Rust and water at the quick exhaust mean the seal is failing."}, {"q": "The bump tire will not deflate. What is the quickest first check?", "options": ["Replace the bump assembly", "Unscrew the quick exhaust muffler and try again", "Lower the regulator to 50 psi", "Replace the solenoid manifold"], "answer": 1, "why": "A clogged muffler traps air in the tire. Remove it, run louder, and replace it later."}, {"q": "What is the correct tube sheet stack, top to bottom?", "options": ["Hold-down plate, tubes, felt gasket, tube sheet", "Tube sheet, felt gasket, tubes, hold-down plate", "Tube sheet, tubes, felt gasket, hold-down plate", "Felt gasket, tube sheet, tubes, hold-down plate"], "answer": 1, "why": "Sheet, felt, tubes through, then the hold-down plate and about 15 bolts at 30 ft-lbs. Out of order, the felt does not seal."}, {"q": "You are replacing tubes on an old unit with a circular downcomer diffuser. What should you confirm?", "options": ["That the new 48 in tubes will not catch on the downcomer slats", "That the tubes are 36 in", "That the window is 6 in", "That the lining is Flexcel 3000"], "answer": 0, "why": "Only 48 in replacement tubes are supplied now, and 48 in tubes can catch on downcomer slats that were built for shorter tubes."}, {"q": "Which window is tight for tube washing?", "options": ["The 6 in window on current units", "The 4 in window on older FP and Assero units", "The flanged split tank window", "The effluent connection"], "answer": 1, "why": "Older FP and Assero units have a 4 in window. Current units standardize on 6 in because the 4 in was a tight access way."}]}, {"id": "05", "slug": "pneumatics", "title": "Pneumatics and Valve Actuators", "tagline": "Air supply, the solenoid manifold, dual-acting actuators, and the pneumatic mistakes we see in the field", "scenes": [{"dur": 12, "shot": "install:group air", "layout": "center", "h": "Pneumatics and Valve Actuators", "p": ["Compressed air does three jobs on a Defender: it opens and closes the precoat valve, opens and closes the effluent valve, and inflates and vents the bump tire. This module covers the air supply, the manifold, and the actuators."]}, {"dur": 18, "shot": "install:marks D20", "layout": "left", "h": "The compressor: 150 psi and 5.2 CFM", "p": ["We ship an Ingersoll Rand 5 hp compressor with every system. Really all you need is 150 psi of air feeding in and about 5.2 cubic feet per minute.", "A smaller compressor still works. It just takes longer to refill between bump cycles."], "stats": [{"n": 150, "suffix": " psi", "label": "Supply pressure"}, {"n": 5.2, "suffix": " CFM", "label": "Air delivery"}]}, {"dur": 16, "shot": "install:overview", "layout": "right", "h": "One compressor, up to three Defenders", "p": ["We recommend one compressor per system, but you can run up to three Defenders on one. In that case keep each unit at 10 bumps, or you will be waiting for the tank to refill.", "Link the controllers so they do not bump at the same time. That is the only reason to link them."]}, {"dur": 20, "shot": "install:marks D13", "layout": "left", "h": "Filter regulator: set it to 85 psi", "p": ["The filter regulator on the tank sets the pressure going into the system. We want 85 psi. I have seen systems at 100, and some older ones at 120, but we still like 85.", "The RMF12 air pressure sensor reads 0 to 100 psi. The closer you get to 100, the fuzzier that signal gets, and it can throw an error even though you are at pressure. Eighty-five is the Goldilocks zone."], "stats": [{"n": 85, "suffix": " psi", "label": "Regulator setting"}, {"n": 100, "suffix": " psi", "label": "Sensor ceiling on RMF12"}]}, {"dur": 16, "shot": "install:marks D21,D13", "layout": "right", "h": "Water separator and tubing", "p": ["A water separator sits with the regulator to catch condensation before it reaches the solenoids. We ship 200 to 500 ft of poly tubing with the system.", "Tubing and fittings are standard sizes. Home Depot, Lowe's, or McMaster will have them, and it will be cheaper and faster than waiting on us."]}, {"dur": 14, "shot": "install:group air", "layout": "left", "h": "Clear tubing does not like sunlight", "p": ["The tubing we ship is clear. On an outdoor install in strong sun, Texas for example, it can wear out in about a month.", "Indoors it does not matter. Outdoors, source opaque tubing locally and run it where you can."]}, {"dur": 20, "shot": "rmf12:part manifold", "layout": "right", "h": "The solenoid manifold", "p": ["Inside the panel is the manifold block with three solenoids: bump, precoat or regen valve, and effluent valve. Older units have a fourth for a pneumatic influent valve.", "Air supply comes in on the right side. An air pressure transducer on the block tells the RMF12 how much pressure it has, and that reading is on the screen."]}, {"dur": 18, "shot": "rmf12:part manifold", "layout": "left", "h": "Row A opens. Row B closes.", "p": ["Each valve solenoid has two outputs. The A row feeds the open side of the actuator, the B row feeds the close side.", "The larger port is the bump. It needs more air and more pressure to fill that tire on top."]}, {"dur": 18, "shot": "rmf12:part manifold", "layout": "right", "h": "The LED and the blue test button", "p": ["When the controller energizes a solenoid, an LED lights on it. That tells you the signal made it this far. If the valve still does not move, check the air and the tubing.", "Under each solenoid is a blue manual test button. Press it with a pen and you hear a whoosh of air. That means the solenoid works, before you worry about any signals."]}, {"dur": 20, "shot": "install:marks D7,D8", "layout": "left", "h": "Actuators are dual-acting", "p": ["Many actuators take air one way and spring back. Ours do not. Air on one side opens, air on the other side closes, so you get full control of speed in both directions.", "The bump is the only single-acting function. The tire holds about 90 psi, and the quick exhaust dumps it."]}, {"dur": 22, "shot": "sp55:head", "layout": "right", "h": "Bump tire, quick exhaust, and the muffler", "p": ["To bump, the controller sends air to the quick exhaust valve. It opens, the tire deflates, the tube sheet drops, and then the tire reinflates.", "The small white muffler on the quick exhaust only quiets the bump. If it clogs, the tire cannot deflate. Unscrew it and keep running, louder, and replace it later.", "A muffler turning brown or black means rust and moisture from inside. Check the lift shaft O-rings before putting it back in service."]}, {"dur": 16, "shot": "install:marks D1,D2", "layout": "left", "h": "What is wrong with this picture?", "p": ["No quick exhaust. The air line is plumbed straight into the side of the bump tire. There is nowhere for the air to escape, so this tire will never deflate.", "I have seen some very creative pneumatic tubing in the field. The schematic is in the O&M. Follow it."]}, {"dur": 16, "shot": "install:marks D8", "layout": "right", "h": "Valve runs backwards? Swap the lines.", "p": ["If a valve opens when it should close, the two air lines are on the wrong ports. Swap them at the actuator.", "There is nothing to change in programming. It is purely which line went where."]}, {"dur": 22, "shot": "install:marks D8", "layout": "left", "h": "Slamming valve? Adjust the needle valves.", "p": ["On the bottom of the actuator are two needle valves. Counterclockwise lets more air in and speeds it up, clockwise slows it down. Adjust with air applied, by feel and by look, because there is no exact science.", "A system that worked for years and now slams shut in precoat usually has a little debris in a needle valve. Open it up or close it down until it moves smooth."]}, {"dur": 16, "shot": "install:marks D7", "layout": "right", "h": "Travel stops and the toolkit valve", "p": ["The silver set screws are the travel stops, and they set where open and closed land. Someone bumps them, or vibration moves them, and the valve closes past 90°. Check them.", "The flow control valve in the Defender toolkit takes one air line and switches between open and close, so you can work a valve by hand during setup."]}, {"dur": 14, "shot": "install:marks D7,D8", "layout": "left", "h": "Read the indicator", "p": ["The red line on the actuator indicator shows where the disc is. Perpendicular to the pipe means closed. In line with the pipe means open.", "Watch it travel. We want a smooth turn, not a jolt and a slam."]}, {"dur": 20, "shot": "install:marks D7", "layout": "right", "h": "Stuck valve: is it the valve or the actuator?", "p": ["Unbolt the actuator at the flange, put a wrench on the bare stem, and work the valve. If the valve turns freely, the actuator is the problem. Adjust the needle valves, and if it still will not move, replace it.", "Actuators carry a 3 or 5 year warranty, and they all run on the same air, old system or new. Let us know and we will send one out."]}, {"dur": 18, "shot": "install:marks D7", "layout": "left", "h": "Aggressive water seizes valve shafts", "p": ["One contractor had a site with Teflon and other chemicals in the water. The effluent valve would open, seize, work once after cleaning, then seize again. The shaft inside the valve was coated.", "Valve coatings can be chemically attacked. Tell us what is in the water up front so we can recommend the right valve."]}, {"dur": 14, "shot": "install:group air", "layout": "right", "h": "Compressor never shuts off? Leak test.", "p": ["A compressor that runs constantly means a leak somewhere on the lines. Soapy water along every pneumatic line is the quickest way to find it.", "A tiny crack in one tube can drop the pressure enough that a valve never fully opens."]}, {"dur": 18, "shot": "card", "layout": "center", "h": "The valve troubleshooting chain", "p": ["When a valve will not move, start at the controller and work outward to the valve. Most of these are solved before step four."], "table": {"head": ["Step", "Check"], "rows": [["1", "PLC output LED is on for that valve"], ["2", "Solenoid LED is on at the manifold"], ["3", "Blue test button gives a burst of air"], ["4", "Tubing for cracks, lines on the right ports"], ["5", "Needle valves and travel stops"], ["6", "Actuator itself, then call us"]]}}, {"dur": 16, "shot": "card", "layout": "center", "h": "Three things to remember", "p": ["Set the regulator to 85 psi. The RMF12 sensor tops out at 100, and the signal gets fuzzy up there.", "Row A opens, row B closes, and a valve running backwards just needs its two air lines swapped.", "Needle valves counterclockwise for faster, clockwise for slower, and always confirm the quick exhaust is actually installed on the bump tire."]}], "quiz": [{"q": "What should the filter regulator on an RMF12 system be set to, and why?", "options": ["120 psi, to make sure the tire fully inflates", "100 psi, the top of the sensor range", "85 psi, because the 0 to 100 psi sensor gets unreliable near the top", "50 psi, to extend O-ring life"], "answer": 2, "why": "The RMF12 air sensor reads 0 to 100 psi, and the signal gets fuzzy near 100. Eighty-five keeps you in the clean part of the range."}, {"q": "The effluent valve closes when the controller calls for it to open. What is the fix?", "options": ["Change the valve direction parameter on the RMF12", "Swap the two air lines at the actuator", "Replace the solenoid on the manifold", "Turn both needle valves fully clockwise"], "answer": 1, "why": "Actuators are dual-acting, so a backwards valve just has its open and close lines on the wrong ports. No programming change is needed."}, {"q": "A precoat valve slams open during every cycle. Which adjustment slows it down?", "options": ["Turn the needle valve on the actuator clockwise", "Turn the needle valve on the actuator counterclockwise", "Lower the regulator to 60 psi", "Press the blue test button on the solenoid"], "answer": 0, "why": "Clockwise restricts air into the actuator and slows the stroke. Counterclockwise lets more air in and speeds it up."}, {"q": "The bump tire will not deflate. What do you check first?", "options": ["The felt gasket", "The quick exhaust muffler for clogging, and that a quick exhaust is installed", "The flow meter jumper", "The precoat valve travel stops"], "answer": 1, "why": "A clogged muffler, or an air line plumbed straight into the tire with no quick exhaust, leaves the air nowhere to go. Unscrew the muffler and keep running."}, {"q": "A solenoid LED is lit but the valve does not move. What is the next test?", "options": ["Replace the PLC", "Press the blue manual test button and listen for a burst of air", "Reset the RMF12 alarm history", "Reprogram parameter 45"], "answer": 1, "why": "The LED proves the signal reached the solenoid. The blue button proves the solenoid and air path work, which sends you to the tubing and actuator next."}, {"q": "Three Defenders share one compressor. How many bumps per cycle should each run?", "options": ["5, to save air", "10, and link the controllers so they do not bump together", "20, since the compressor is oversized", "30, one unit at a time"], "answer": 1, "why": "Keep each system at 10 bumps on a shared compressor or you wait for the tank to refill, and link the controllers so they bump at different times."}]}, {"id": "06", "slug": "controller", "title": "The RMF12 Controller", "tagline": "Controller generations, what is inside the panel, the known issues, and every screen you will actually use", "scenes": [{"dur": 12, "shot": "rmf12:closed", "layout": "center", "h": "The RMF12 Controller", "p": ["The RMF12 is the brain of the Defender. This module covers the controller generations you will meet in the field, the parts inside the panel, the three known issues, and the screens, parameters, alarms, and data logs."]}, {"dur": 22, "shot": "rmf12:closed", "layout": "left", "h": "Four generations of controller", "p": ["The oldest is the Command Center, built custom per project. Beyond digging up project files, there is not much we can do for those.", "The RMF8 is the push-button, relay-based panel. Less functionality, but perfectly serviceable. We no longer sell the parts, but we have the full component list so you can source them.", "The RMF11 lost its supplier after COVID, so parts are scarce. If you have an 8 or an 11, we recommend upgrading to the 12."], "table": {"head": ["Controller", "Status"], "rows": [["Command Center", "Custom per project, project files only"], ["RMF8", "Push-button, relay based, parts list available"], ["RMF11", "Supplier gone, few parts, upgrade"], ["RMF12", "2020 to present, Siemens, data logging"]]}}, {"dur": 16, "shot": "rmf12:open", "layout": "right", "h": "RMF12: all Siemens, since 2020", "p": ["Everything inside the 12 is Siemens: the PLCs, the power supply, the touchscreen HMI. It is a very reliable controller, and it logs data, which is why we push the upgrade.", "When you upgrade from an RMF8, the terminal numbers changed. There is a conversion sticker inside the panel that maps old to new."]}, {"dur": 20, "shot": "rmf12:part plc", "layout": "left", "h": "Three PLCs and what the LEDs mean", "p": ["Three main PLCs run the system. The LEDs on each one tell you the valve is working, the pump is working, the sensor is reading. Green across the board means nothing on the PLCs is your problem.", "Red or yellow means a sensor or signal issue. No LED at all usually means something is disconnected and needs reconnecting."]}, {"dur": 16, "shot": "rmf12:part psu", "layout": "right", "h": "No green light here, nothing works", "p": ["We feed the panel 120 VAC. Everything inside runs on 24 VDC, and this power supply does the conversion.", "If you do not see the green LED on the power supply, it is not sending 24 V down and nothing in the panel is powered. Check it first."]}, {"dur": 18, "shot": "rmf12:part tb1", "layout": "left", "h": "T is top row, B is bottom row", "p": ["Everything you land goes on this terminal strip. Terminals are labeled T for top row and B for bottom row.", "As much as it pains me, the printed labels look reversed at first glance. Read them carefully. Once you learn how it reads, any terminal is easy to find."]}, {"dur": 18, "shot": "rmf12:part tb1", "layout": "right", "h": "Push-button and screwdriver terminals", "p": ["The newer orange terminals are push buttons. Press, insert the wire, release.", "Older strips are spring clamps. Slot a small screwdriver in, push down to open the spring, then land or pull the wire. God gave you two hands for a reason."]}, {"dur": 16, "shot": "rmf12:part breaker", "layout": "left", "h": "The internal breaker", "p": ["Quick tip: there is a small breaker inside the panel. Use it to kill power to the controller without walking back to the main breaker.", "When you turn it back on, watch the PLCs light up. Green across the board and the panel is back."]}, {"dur": 18, "shot": "rmf12:part switch", "layout": "right", "h": "Ethernet switch: BMS, Modbus, email", "p": ["The switch at the top is for a building management system or network connection. Modbus, email alerts, and remote monitoring all go through here, and there is an advanced setup guide for each.", "Most of that access is read-only. You can see every sensor and every log, but there is very little write access. Clearing an alarm remotely takes a very specific setup."]}, {"dur": 18, "shot": "rmf12:part hmi", "layout": "left", "h": "Known issue: frozen HMI screen", "p": ["If the touchscreen freezes, cycle power once or twice. Most of them come back and never do it again.", "If it keeps happening, call us. We replace those no questions asked. We do ask for the old one back so we can help Siemens get to the bottom of it."]}, {"dur": 16, "shot": "rmf12:part breaker", "layout": "right", "h": "Known issue: stuck on the desktop at boot", "p": ["On startup the HMI shows a desktop, then loads the program. If it stays on the desktop, reset the internal breaker and it should launch.", "If it still will not, the software needs a reload. RMF11 and earlier we can email. The RMF12 has to go out on a Siemens-branded SD card."]}, {"dur": 18, "shot": "rmf12:part plc", "layout": "left", "h": "Known issue: effluent LED on, valve not moving", "p": ["The telltale sign: the PLC LED for the effluent valve is on, so the PLC thinks it is sending the signal, but nothing happens downstream.", "That is buildup on the contactor in the PLC. Quickest fix is a replacement PLC from us. Give us a call."]}, {"dur": 18, "shot": "rmf12:closed", "layout": "right", "h": "The home screen", "p": ["Top left shows which of the four modes you are in, the status of each valve and the pump, and time remaining for a precoat or bump. Upper right is the differential pressure.", "Everything starts from this screen. The Menu button is where the rest of the controller lives, and we will walk through it next."]}, {"dur": 20, "shot": "rmf12:closed", "layout": "left", "h": "Logging in, and End Precoat", "p": ["Press Menu, then Setup, and it asks for the password. Once you are logged in it will not ask again, and back on the home screen an End Precoat button appears.", "That button is hidden on purpose. We do not want a random operator ending a precoat early and sending media back to the pool. Sites can set their own password."]}, {"dur": 22, "shot": "rmf12:closed", "layout": "right", "h": "What is in the Menu", "p": ["Flex Clean walks a chemical clean step by step and then bumps and precoats on its own while it soaks. Drain and Rinse walks a media change, flashing the valve to operate next.", "VFD Info shows horsepower and voltage if the drive is connected, and Vacuum Transfer turns the vacuum on and off. Clean Strainer shuts the system down for a new operator to pull the basket. Then View and Setup."], "table": {"head": ["Menu item", "What it does"], "rows": [["Flex Clean", "Guided chemical clean with auto bump and precoat"], ["Drain and Rinse", "Guided media change"], ["VFD Info", "Drive data when connected"], ["Vacuum Transfer", "Vacuum on and off"], ["Clean Strainer", "Guided shutdown for the basket"], ["View, Setup", "Status screens, parameters, advanced settings"]]}}, {"dur": 18, "shot": "rmf12:closed", "layout": "left", "h": "I/O Diagnostics: every output is a switch", "p": ["Setup, then Advanced Settings, then I/O Diagnostics. Each valve, the pump, and the other outputs become an on and off switch.", "Use it for dry testing on a new install and for adjusting actuators. Open the regen valve from here, tune the needle valves, close it, repeat."]}, {"dur": 22, "shot": "rmf12:closed", "layout": "right", "h": "Parameters: watch the units", "p": ["Setup, then Parameters. There are about 40 to 60, all listed in the O&M, and most are factory set. Precoat cycle time, bump auto time, and the fireman delays live here.", "Be careful with units, because some are in minutes and some are in seconds. Six hundred seconds is 10 minutes. The fireman delays are in seconds."]}, {"dur": 16, "shot": "rmf12:closed", "layout": "left", "h": "Flex Clean bumping nonstop", "p": ["If a Flex Clean bumps continuously for 24 hours, someone has set the bump auto time too low, a second or two. Look at parameters 12 through 15.", "Reset it so the soak bumps about once an hour. If you are not sure of the number, text the support line and it will give you the parameter and the setting."]}, {"dur": 16, "shot": "rmf12:closed", "layout": "right", "h": "Red alarms must be reset", "p": ["A red alarm stops the system until it is cleared. Press the flashing alarm button, then Reset Alarm.", "The full history stays after a reset, so you can always go back and see what happened. The error code list is on the website."]}, {"dur": 22, "shot": "rmf12:part hmi", "layout": "left", "h": "Data logs on the SD card", "p": ["Behind the HMI is an SD card logging bump counts, differential pressure, run times, and more. Pull it, copy the zip file, put it back, and email the zip to nbts@xyleminc.atlassian.net.", "We run a full diagnostic report and can solve a lot remotely. Check the controller clock first. If it thinks January is June, the data is still good, we just shift the dates.", "A phone dongle and a portal upload are in the works so you do not need a laptop on site."]}, {"dur": 12, "shot": "rmf12:closed", "layout": "right", "h": "The O&M is on the panel", "p": ["Every RMF12 panel carries a QR code to the O&M, and tech support will be on there shortly too. If you land on a site with no manual, it is on the door."]}, {"dur": 16, "shot": "card", "layout": "center", "h": "Three things to remember", "p": ["Green LEDs on the power supply and all three PLCs, and T is the top row even though the labels look reversed.", "Frozen screen means cycle power, stuck on the desktop means reset the internal breaker, effluent LED on with no movement means a new PLC.", "Log in for End Precoat, watch seconds versus minutes in Parameters, and send us the SD card zip when something is not right."]}], "quiz": [{"q": "Nothing in the panel has power, but the main breaker is on. What do you check first?", "options": ["The Ethernet switch link lights", "The green LED on the 24 VDC power supply", "The SD card behind the HMI", "Parameter 45"], "answer": 1, "why": "The power supply converts 120 VAC to 24 VDC. No green LED means nothing downstream is powered."}, {"q": "Which row of the terminal strip is T?", "options": ["The bottom row", "The top row", "The row closest to the door", "Either, depending on the panel year"], "answer": 1, "why": "T is top and B is bottom. The printed labels look reversed at first, so read them carefully."}, {"q": "The HMI boots to a desktop and never loads the program. First move?", "options": ["Order a new HMI", "Reset the internal breaker in the panel", "Remove the SD card", "Press End Precoat"], "answer": 1, "why": "A breaker reset usually launches the program. If it persists, the RMF12 software reload has to come on a Siemens SD card."}, {"q": "The effluent valve PLC LED is on, but the valve does not open. Likely cause?", "options": ["Wrong password", "Contactor buildup inside the PLC, replace the PLC", "Flow meter installed backwards", "Bump auto time set too low"], "answer": 1, "why": "When the PLC shows the output on but nothing happens, it is buildup on the PLC contactor. We send a replacement PLC."}, {"q": "How do you make End Precoat appear on the home screen?", "options": ["Hold the mode indicator for 5 seconds", "Open I/O Diagnostics and toggle the regen valve", "Menu, Setup, enter the password, then return home", "Reset the internal breaker"], "answer": 2, "why": "End Precoat only shows after login so a random operator cannot cut a precoat short and send media to the pool."}, {"q": "A Flex Clean is bumping nonstop. What has happened?", "options": ["The muffler is clogged", "The bump auto time parameter was set too low, in seconds", "The fireman delay is in minutes", "The differential alarm is set to 15 psi"], "answer": 1, "why": "Bump auto time set to a second or two makes Flex Clean bump continuously. Reset it so it bumps about once an hour."}]}, {"id": "07", "slug": "electrical", "title": "Electrical: RMF12, VFD and Flow Meter", "tagline": "The three signals between the panel and the drive, the flow meter, Danfoss programming, and the interlocks", "scenes": [{"dur": 14, "shot": "rmf12:open", "layout": "center", "h": "Electrical: RMF12, VFD and Flow Meter", "p": ["Out of about 2,000 support tickets this year, the biggest one is how do I set up my RMF panel with my VFD. This module walks the three signals, the flow meter, the Danfoss parameters that matter, and the interlocks."]}, {"dur": 18, "shot": "install:marks D12,F33,F37", "layout": "left", "h": "The base package is three items", "p": ["RMF12 panel, a VFD or motor starter, and a flow meter. If you have those three from our side, you have the basic package and can get the system running.", "The RMF12 should be the brain. It controls the drive and the interlocks and passes data down to a BMS or Modbus, not the other way around. It is much harder to help you when something else is in charge."]}, {"dur": 24.5, "shot": "anim:rmf12-drive-wiring", "layout": "bottom", "h": "Three signals, three sets of wires", "p": ["Everything on the RMF12 side is already programmed. Land these, enter motor data on the drive, and you are running."], "table": {"head": ["Signal", "RMF12", "Danfoss"], "rows": [["Run confirm", "B24+ and T17", "Relay 1, terminals 1 and 2"], ["Pump start and stop", "T39 and T40", "12 (or 13) and 18"], ["Precoat jog speed", "T40 jumper to T58, T57 out", "19"], ["Flow meter", "Not to the RMF12", "Meter 1 to 13, meter 3 to 54"]]}}, {"dur": 13.5, "shot": "card", "layout": "bottom", "h": "Run confirm: B24+ and T17", "p": ["Two wires from B24+ and T17 go to relay 1 on the Danfoss, terminals 1 and 2. That relay closes when the motor is running and tells the RMF12 the pump is actually on.", "On the Danfoss those relay terminals are buried behind a cover plate. It is labeled Relay 1 with three terminals. You have to pull the plate to get at them."]}, {"dur": 13, "shot": "card", "layout": "bottom", "h": "Start and stop: T39 and T40", "p": ["T40 carries 24 VDC. When the RMF12 wants the motor, it closes T39 to T40. Those two wires land on the Danfoss right under the keypad: terminal 12 or 13, both 24 VDC out, and terminal 18, digital in.", "We say 12 in the instructions, but 12 and 13 both work. That one contact starts and stops the motor for filter, precoat, bump, and I/O Diagnostics."]}, {"dur": 17.5, "shot": "card", "layout": "bottom", "h": "Jog speed: the jumper everyone asks about", "p": ["Jumper T40 to T58. T58 is the common of a programmable relay in the panel. T57 is its normally open contact, B59 the normally closed.", "One wire from T57 goes to Danfoss terminal 19, digital in, right next to your start command. That relay only energizes in precoat, so terminal 19 only sees voltage in precoat, and the drive drops to jog speed.", "If filter mode runs at 55 to 60 Hz, set jog at 35 to 45 Hz. That is what keeps a big pump from blowing perlite through the tubes."]}, {"dur": 18, "shot": "card", "layout": "bottom", "h": "Flow meter wires to the VFD only", "p": ["The flow meter is the one thing that does not touch the RMF12. Meter terminal 1 goes to Danfoss 13, or 12 if you used 13 for the start signal. Meter terminal 3 goes to 54, analog in.", "That 4 to 20 mA signal is what the drive's PID loop holds the gpm set point with. Use about 18 AWG for all of this signal wiring. Solid or stranded is personal preference."]}, {"dur": 17.5, "shot": "card", "layout": "bottom", "h": "Danfoss programming: the groups", "p": ["Parameters are in groups: 0-xx sets up the display so you can see Hz, amps, RPM, and gpm. 1-xx is motor and load, where you enter horsepower, RPM, and full load current from the motor plate.", "3-xx is reference and limits: maximum and minimum reference, 4 mA and 20 mA scaling on the analog input, and the set point. Of the 50 or so parameters, those five are what you really need. The rest is in the commissioning guide."]}, {"dur": 20, "shot": "rmf12:terminals B-24+,T-17", "layout": "left", "h": "Main pump offline", "p": ["About 5 seconds after you press Start, if the RMF12 has no run confirm, it alarms Main pump offline and stops. I get calls on this one constantly. Check that the VFD is on and the wiring is right.", "In our demo the VFD was switched off, and the system cut out immediately. If the motor is running but the drive has no way to send the signal, jumper T17 to B24+ and the alarm clears."]}, {"dur": 16, "shot": "rmf12:closed", "layout": "right", "h": "Parameter 45: optional relay 1", "p": ["On the RMF12 side this is the only thing you set. Parameter 45 picks when that relay is active: 1 is idle, 2 is precoat, 3 is filter, 4 is custom.", "Set it to 2 for jog speed. Everything else in the panel is factory programmed."]}, {"dur": 18, "shot": "install:marks F37", "layout": "right", "h": "The switch behind the Danfoss keypad", "p": ["Every one of these drives ships set to digital input. Behind the keypad is a tiny switch that has to be flipped to analog for the flow meter signal.", "It is the most obnoxious thing in these drives and the most common cause of a VFD not reading the flow meter. Pop the keypad off and check it before anything else."]}, {"dur": 18, "shot": "install:marks F33,F37", "layout": "right", "h": "Closed loop or open loop", "p": ["With a flow meter you run closed loop. Tell it 500 gpm and the PID loop ramps the motor up and down to hover there. Without a meter you run open loop at a fixed speed set on the keypad.", "Below 4 mA is a bad signal. If the drive sees it in the dirt, redo the wiring. Once the drive is programmed, the RMF12 handles start, stop, and jog, and you should never touch it again."]}, {"dur": 14, "shot": "rmf12:closed", "layout": "left", "h": "Danfoss PC software and other drives", "p": ["Danfoss offers free PC software. Build the parameters once, then upload through a USB-to-serial cable at each site.", "Pentair-branded integrated drives have their own commissioning instructions. For ABB or anything else, digital in, digital out, and analog in are consistent. Only the terminal numbers change, and the support line can convert them."]}, {"dur": 18, "shot": "install:marks F37", "layout": "right", "h": "Signet flow meter: size, jumper, mounting", "p": ["Size the meter to the pipe. A 2 in meter on a 10 or 12 in line cannot handle the flow and will not give a good signal. We recommend the blind meter and read flow on the drive.", "A small blue jumper on the terminal block sets analog, digital, or frequency out. Ours ship on analog. Verify it on any third-party meter.", "Horizontal or vertical run, and position on the pipe does not matter much. If it is off a couple of percent, that is what the PID loop is for."]}, {"dur": 18, "shot": "card", "layout": "center", "h": "Flow meter LED codes", "p": ["There are flow arrows all over the meter and the saddle. Alternating red and blue almost always means it is in backwards."], "table": {"head": ["LED", "Meaning"], "rows": [["Blinking blue", "Normal, reading flow"], ["Solid blue", "Pipe full, no flow"], ["Off", "No power"], ["Alternating red and blue", "Sees water and flow, likely installed backwards"]]}}, {"dur": 20, "shot": "rmf12:terminals T-45,T-46,T-48,T-49,T-51,T-52", "layout": "left", "h": "Filter mode contacts", "p": ["Three contacts close only in filter mode: 46 and 45, 49 and 48, 52 and 51. Use them for the chemical controller, so it only doses with flow, or to run an outlet for chemical pumps through a relay or contactor.", "They can give 24 VDC out or act as a normally open or normally closed signal, whatever the equipment wants. Simple, stupid is the best way with these."]}, {"dur": 18, "shot": "rmf12:terminals T-54,T-55", "layout": "right", "h": "Fireman contacts for heaters and UV", "p": ["Terminals 55 and 54 are the fireman contacts. Instead of plain on and off, they have a programmable delay on and delay off so a heater, boiler, or UV ramps down before the flow stops. Nothing should overheat with no water moving.", "We recommend about 5 minutes. The parameter is in seconds, so convert. UV interlocks get their own session."]}, {"dur": 16, "shot": "rmf12:part tb1", "layout": "left", "h": "Where to get help on this", "p": ["There is a step-by-step wiring animation of the RMF12 and the Danfoss, plus commissioning guides for Danfoss and GreenDrive with ABB in progress.", "A large customer recently swapped a Danfoss for an ABB. The support line read both manuals and converted the terminals with them over the phone. Call or text it from the pump room."]}, {"dur": 16, "shot": "card", "layout": "center", "h": "Three things to remember", "p": ["Run confirm B24+ and T17 to relay 1, start and stop T39 and T40 to 12 and 18, jog jumper T40 to T58 with T57 out to 19 and parameter 45 set to 2.", "Flow meter 1 to 13 and 3 to 54, and flip the analog switch behind the Danfoss keypad before you blame anything else.", "Filter mode contacts for anything that needs flow, fireman contacts with a 5 minute delay for heaters and UV."]}], "quiz": [{"q": "The RMF12 alarms Main pump offline about 5 seconds after Start. What is missing?", "options": ["The flow meter signal on terminal 54", "The run confirm from the VFD on B24+ and T17", "The jog speed jumper", "The fireman delay"], "answer": 1, "why": "Main pump offline means no run confirm reached the RMF12. Check the VFD is on and the B24+ and T17 wiring to relay 1."}, {"q": "Where does the Signet flow meter signal land?", "options": ["RMF12 terminals T39 and T40", "RMF12 terminals B24+ and T17", "Danfoss terminals 13 (or 12) and 54, never the RMF12", "The Ethernet switch"], "answer": 2, "why": "The flow meter is the one item that wires only to the VFD: terminal 1 to 13 for power and terminal 3 to 54, analog in, for the PID loop."}, {"q": "The Danfoss is wired correctly but shows no flow reading. Most likely cause?", "options": ["The analog/digital switch behind the keypad is still on digital", "Parameter 45 is set to 3", "The internal breaker is off", "The meter is a blind model"], "answer": 0, "why": "Danfoss drives ship on digital input. The switch behind the keypad must be flipped to analog, and it is the most common cause of a VFD not reading flow."}, {"q": "What makes the drive drop to jog speed only during precoat?", "options": ["The flow meter reading drops below 4 mA", "T57 to terminal 19, with parameter 45 set to 2 so the relay energizes only in precoat", "The fireman contact opens", "The run confirm relay opens"], "answer": 1, "why": "T40 jumpered to T58 feeds the programmable relay, T57 goes to Danfoss 19, and parameter 45 at 2 makes that relay active only in precoat."}, {"q": "The flow meter LED alternates red and blue. What do you check?", "options": ["The pipe is empty", "The meter has no power", "The flow arrows, since it is probably installed backwards", "The 18 AWG wire gauge"], "answer": 2, "why": "Alternating red and blue means it senses water and flow but is likely mounted against the flow direction."}, {"q": "You need a heater to shut down 5 minutes before the pump stops. Which contacts?", "options": ["Filter mode contacts 46 and 45", "Fireman contacts 55 and 54 with the delay parameters in seconds", "Run confirm B24+ and T17", "T39 and T40"], "answer": 1, "why": "Fireman contacts have programmable delay on and delay off for heaters, boilers, and UV. Set about 300 seconds for 5 minutes."}]}, {"id": "08", "slug": "startup", "title": "Startup and Commissioning", "tagline": "The checks before you press Start, the first bump and precoat, confirming filter mode, and what every new build needs after its first run", "scenes": [{"dur": 12, "shot": "install:overview", "layout": "center", "h": "Startup and Commissioning", "p": ["This module is the startup in order: controller powered and dry tested, air at pressure, water and drains ready, pump and VFD programmed, then Start, bump, precoat, and into filter mode. Plus what a new build needs right after."]}, {"dur": 18, "shot": "rmf12:open", "layout": "left", "h": "Power the controller early and test", "p": ["Get 120 V to the RMF12 as soon as you can. Green LED on the power supply, green across the three PLCs, and the HMI loads past the desktop into the program.", "Then use I/O Diagnostics under Setup and Advanced Settings. Every valve and the pump becomes an on and off switch, so you can dry test and tune actuators before there is water in the tank."]}, {"dur": 18, "shot": "install:marks D13,D20", "layout": "right", "h": "Air on, 85 psi at the regulator", "p": ["Compressor running, regulator set to 85 psi. The RMF12 reads that pressure through a 0 to 100 psi transducer, and you can see the reading on the controller. Anywhere in the 80 to 90 range is right.", "Do not run a new panel at 100 or 120. The sensor gets fuzzy at the top of its range and will throw errors at full pressure."], "stats": [{"n": 85, "suffix": " psi", "label": "Regulator setting"}]}, {"dur": 18, "shot": "install:marks D10,D15,D17", "layout": "left", "h": "Water, drains, and the vacuum unit", "p": ["Water in the pool and in the lines. Know where the tank drain goes and what the local health department wants there. Some require an air gap, a DE screen, or a separation tank for perlite.", "The vacuum transfer unit is wired into the junction box on the tank. If it came with a plug, cut it off and land the leads. You will need it to load media."]}, {"dur": 18, "shot": "install:marks F33,F37", "layout": "right", "h": "Pump ready, VFD programmed", "p": ["Power the VFD, enter the motor data from the plate, scale the flow meter input, and set the flow set point. Land the three signal sets to the RMF12 and set parameter 45 to 2.", "With the drive programmed, the RMF12 handles start, stop, and jog speed from here on. See the electrical module for every terminal."]}, {"dur": 20, "shot": "install:group influent", "layout": "left", "h": "Walk the influent line", "p": ["Before you press Start, walk the influent line from the pool to the tank. Every valve open, no blockages anywhere along it.", "Chain-wheel and gear-operated valves especially. Confirm they are actually open. We are making sure the pump is not deadheaded or run dry on its first start."]}, {"dur": 16, "shot": "install:group vent", "layout": "right", "h": "Find the vents before you need them", "p": ["There are at least two manual vents: one at the high point of the precoat loop and one on top of the tank or the effluent. Know where they are.", "On a brand new startup you will be opening them by hand to purge air out of the tank and the piping. Trapped air knocks perlite off the tubes."]}, {"dur": 26, "shot": "sp55:mediachange", "layout": "left", "h": "Load the media", "p": ["Close the valves so the empty tank becomes the vacuum. Open the vacuum transfer line, put the hose in the bag, and turn the vacuum on from the screen. Harborlite bags have a spout, so do not cut the bag open.", "Load the full nameplate amount, rounded up to the next bag. More is fine, less is not, and sit on the bag to work the air out as it empties.", "Perlite is not hazardous, but glasses and a mask are good practice. If you ever handle DE, the mask is not optional."]}, {"dur": 16, "shot": "sp55:window", "layout": "right", "h": "Fill and purge until the vents run water", "p": ["Close the vacuum line, open the inlet, and fill. Crack the drain for a moment to flush the sediment that settles at the bottom.", "Keep filling until water comes out the vents, not just until it passes the window. The air you leave in now is the vibration that ruins your first precoat."]}, {"dur": 16, "shot": "rmf12:closed", "layout": "left", "h": "No alarms, then press Start", "p": ["Clear any red alarm on the flashing alarm button. VFD on. Then press Start.", "The system goes straight into a bump cycle, 10 bumps, then a precoat. Watch the bumps remaining count on the home screen."]}, {"dur": 18, "shot": "rmf12:closed", "layout": "right", "h": "Our own startup alarmed. Here is why.", "p": ["On the demo I pressed Start with the VFD switched off behind me. No run confirm came back, and the system cut out at once with Main pump offline.", "That is the call I get most. Reset the alarm, turn the drive on, Start again, and it goes straight into precoat."]}, {"dur": 22, "shot": "sp55:precoat", "layout": "left", "h": "Precoat: watch the sight glass and the window", "p": ["The pump restarts at jog speed and perlite loops through the precoat line. The sight glass is milky and the whole window is cloudy. That is the perlite in suspension.", "A new system with clean water clears in about 5 to 6 minutes. We still let it run 10. If a site needs more than 20, call us before you keep stretching it.", "Perlite piling up on the tank wall or the window edge is normal. It binds to itself. You are not losing anything."]}, {"dur": 16, "shot": "rmf12:closed", "layout": "right", "h": "End Precoat, or let it time out", "p": ["When the sight glass is clear and you can see the tubes evenly coated, precoat is done. It ends on its own at 10 minutes.", "To end it sooner, Menu, Setup, enter the password, back to home, and End Precoat appears. It is behind the login so an operator cannot cut it short and send media to the pool."]}, {"dur": 20, "shot": "sp55:filter", "layout": "left", "h": "Confirm filter mode and 1 to 3 psi", "p": ["When precoat ends the effluent valve opens and the precoat valve closes about 5 seconds later to avoid water hammer. Do not worry if you still see water in the precoat line for a moment.", "Home screen reads Filter. Effluent open, precoat closed, pump on, flow at set point. Differential should sit at about 1 to 3 psi on a fresh coat."], "stats": [{"n": 3, "suffix": " psi", "label": "Clean differential, top of the 1 to 3 range"}, {"n": 10, "suffix": " min", "label": "Standard precoat"}]}, {"dur": 16, "shot": "sp55:window", "layout": "right", "h": "Patchy coat? Bump and precoat again.", "p": ["The first coat after fresh media is not always even. Look through the window. If you see bare sections, run another bump and precoat before you walk away.", "If it is good the first time, no problem. If it is still patchy after the second, that is when we look at air, precoat speed, and media quantity."]}, {"dur": 22, "shot": "sp55:tubes", "layout": "left", "h": "New builds: early media change, tube wash, ChemClean", "p": ["A Defender cleans very, very well, which is a problem on a brand new build. Everything sitting in that new piping, debris, grease, and oil, goes straight into the filter on the first run.", "Plan an early media change, a tube wash, and a ChemClean Express or degreaser soon after startup. Then load fresh media and run normally.", "One commissioner precoated for three days and never liked the window. On a first startup that is almost always a tube wash and a chemical clean, not a bad filter."]}, {"dur": 18, "shot": "sp55:orbit", "layout": "right", "h": "From the room: the new park routine", "p": ["One contractor opens a new park by acid washing, running the system so the media picks up everything in the pipes, then changing the media within a week or two and cleaning the filter. After that, once a month is plenty.", "Same with a green pool at season opening. The filter will bloom with it. Change the media, clean the tubes, and move on."]}, {"dur": 16, "shot": "sp55:head", "layout": "left", "h": "Rough first bump? Check the tire history.", "p": ["If a new unit bumps rough or does not actuate smoothly, ask how it was moved. A tank carried on its side with the bump tire deflated can bend the lift shaft.", "That is the first thing we check on a new startup bump complaint, before anything on the controller."]}, {"dur": 16, "shot": "card", "layout": "center", "h": "The startup checklist", "p": ["Run it in this order and skip nothing. Every one of these steps is a tech support call we have already taken."], "table": {"head": ["Step", "Confirm"], "rows": [["1", "Controller powered, PLCs green, I/O dry test done"], ["2", "Air at 85 psi, reading on the controller"], ["3", "Influent line walked, every valve open, vents located"], ["4", "VFD programmed, parameter 45 set to 2, no alarms"], ["5", "Media loaded, tank filled until the vents run water"], ["6", "Start, 10 bumps, precoat until the sight glass clears"], ["7", "Filter mode confirmed, 1 to 3 psi differential"]]}}, {"dur": 16, "shot": "card", "layout": "center", "h": "Three things to remember", "p": ["Walk the influent line before Start so the pump is never deadheaded, and fill until water comes out the vents, not just past the window.", "Start means bump, then precoat. Watch the sight glass, end it logged in or let it time out at 10 minutes, then confirm filter mode and 1 to 3 psi.", "Every new build gets an early media change, a tube wash, and a ChemClean Express, because the filter catches everything the new piping sends it."]}], "quiz": [{"q": "What is the first thing to walk before pressing Start on a new system?", "options": ["The precoat loop vents", "The influent line, confirming every valve including chain and gear valves is open", "The Ethernet connection to the BMS", "The tube sheet bolts"], "answer": 1, "why": "A closed valve on the suction side deadheads or dry-runs the pump on its first start. Walk the line and confirm every valve is open."}, {"q": "During the fill after loading media, when do you stop filling?", "options": ["When water passes the viewing window", "When the sight glass turns white", "When water comes out of the vents", "After 10 minutes"], "answer": 2, "why": "Water past the window still leaves air in the top of the tank. Air causes vibration that knocks perlite off the tubes. Fill until the vents run water."}, {"q": "You press Start and 5 seconds later the panel alarms Main pump offline. First thing to check?", "options": ["The media quantity", "That the VFD is powered on and run confirm is wired to B24+ and T17", "The filter regulator setting", "The felt gasket"], "answer": 1, "why": "Main pump offline means no run confirm came back from the drive. In the demo the VFD was simply switched off."}, {"q": "What tells you a precoat is finished?", "options": ["The compressor shuts off", "The sight glass runs clear and the tubes are visible and evenly coated in the window", "The differential reaches 12 psi", "The effluent valve closes"], "answer": 1, "why": "Clear water in the sight glass and an even coat through the window mean the perlite is back on the tubes. It also times out at 10 minutes."}, {"q": "What differential should a freshly precoated filter show in filter mode?", "options": ["0 psi", "About 1 to 3 psi", "About 10 to 12 psi", "15 psi"], "answer": 1, "why": "Clean media runs at about 1 to 3 psi. Twelve is the auto-bump point and 15 is the alarm."}, {"q": "Why does a brand new installation need an early media change, tube wash, and ChemClean Express?", "options": ["Because the factory media is a different grade", "Because new piping sends debris and oil into the filter on the first run", "Because the warranty requires it", "Because the first precoat uses too much air"], "answer": 1, "why": "The Defender cleans so well that it collects everything left in new piping. Clean it out early and reload fresh media."}]}, {"id": "09", "slug": "mediachange", "title": "The Media Change", "tagline": "Drain and Rinse on the RMF12, rinsing until clear, vacuuming in fresh Harborlite, and purging every bit of air before you precoat", "scenes": [{"dur": 12, "shot": "sp55:orbit", "layout": "center", "h": "The Media Change", "p": ["This module walks a media change the way we do it on the demo skid: when to change, the Drain and Rinse menu, bump, drain, rinse, vacuum in fresh perlite, purge the air, and precoat."]}, {"dur": 18, "shot": "sp55:window", "layout": "left", "h": "When the media is spent", "p": ["Two signs. The differential is 10 psi or more right after a bump, or the media looks fouled through the window: changing color, big debris, bare patches.", "Plan on 4 to 6 weeks. A lazy river runs shorter, a pool with two bathers a month runs longer. An older controller that loops precoat over and over is telling you the same thing."], "stats": [{"n": 10, "suffix": " psi", "label": "Differential after a bump"}, {"n": 4, "suffix": " to 6 wk", "label": "Typical media life"}]}, {"dur": 16, "shot": "rmf12:closed", "layout": "right", "h": "Menu, then Drain and Rinse", "p": ["The RMF12 walks the whole change step by step. The valve you need to operate next flashes on the screen. Operate it, then press Next.", "First prompt is to close the influent. It will keep flashing until you press Next, so do the valve, then the button."]}, {"dur": 20, "shot": "sp55:bump", "layout": "left", "h": "Bump cycle: ten bumps", "p": ["Press Bump Cycle. Ten bumps is the factory setting, and bumps remaining counts down in the top left.", "This knocks every bit of perlite off the tubes and into suspension so it drains out with the water instead of staying on the tubes."]}, {"dur": 14, "shot": "install:marks D10", "layout": "right", "h": "Open the tank drain", "p": ["Press Next and open the drain valve at the bottom of the tank. Most are the manual handle with the extension. Some sites have the automatic pneumatic drain.", "Watch the window on the side. The level dropping past it tells you the tank is emptying."]}, {"dur": 16, "shot": "install:group vent", "layout": "left", "h": "Open the vents so it drains fast", "p": ["Open the manual vent lines at the same time, the one on the precoat loop and the one on top of the tank. A closed tank drains slowly.", "Know where they are on every site before you start. These are manual, and a new operator will not find them on the screen."]}, {"dur": 16, "shot": "sp55:window", "layout": "right", "h": "Optional: pull the window and hose it down", "p": ["If there is a lot of debris stuck inside, you can unbolt the viewing window and spray the tubes down with a garden hose while the tank is drained.", "It saves rinse cycles. Leave one or two bottom bolts in so the heavy cover goes back easier. The full tube wash is covered in the next module."]}, {"dur": 18, "shot": "install:overview", "layout": "left", "h": "Refill to rinse, watch the vents", "p": ["Close the drain, reopen the influent, and let the pump fill the tank. Keep the vents open. When water comes out of the vents, the tank is full.", "Then close the discharge, open the drain and vents again, and let it out. That is one rinse."]}, {"dur": 16, "shot": "card", "layout": "center", "h": "Two rinses is the standard. Clear is the goal.", "p": ["Two rinses is what we recommend. It may take 7, 8, or 10 depending on what went into that filter and how long since the last change.", "The test is the drain water. If you can see perlite or debris in it, rinse again. On a site with an air gap to the floor drain you can actually watch it."]}, {"dur": 18, "shot": "install:marks D14,D17,D19", "layout": "right", "h": "Final drain. Now the tank is a vacuum cleaner.", "p": ["After the last rinse, drain it dry. Close the pump discharge and the other valves, then open the vacuum transfer line on the back of the tank.", "With everything else closed, the vacuum transfer unit pulls on the whole tank. If a valve is open somewhere, it will not pull. That is the usual reason there is no suction."]}, {"dur": 20, "shot": "install:marks D15", "layout": "left", "h": "Use the spout. Do not cut the bag open.", "p": ["Harborlite bags have a built-in spout. Open that, put the hose in, and press Vacuum On. I have watched people slice the bag down the middle and spill perlite across the floor.", "Keep the hose buried in the perlite, not sucking air. As the bag empties, sit on it to push the air out and keep feeding."]}, {"dur": 18, "shot": "card", "layout": "center", "h": "Load the full amount. More is fine.", "p": ["The pounds required are on the nameplate and the decal. Bags are 25 lb, sometimes 45 or 50. Round up to the next full bag.", "A full bag where a half would do is no problem. Too little leaves bare tube, and bare tube coats with grease and dirt. Just do not throw in the whole pallet."]}, {"dur": 14, "shot": "card", "layout": "center", "h": "Handling: glasses and a mask", "p": ["Perlite dust is not hazardous, but safety glasses and a mask are good practice. If you ever work with DE, the mask is not optional.", "Use Harborlite 700. The tube mesh is matched to that grade. Finer grades pass through the tubes, coarser grades give cloudier water."]}, {"dur": 18, "shot": "install:marks D17,D18,D19,D10", "layout": "right", "h": "Close the vacuum, refill, crack the drain", "p": ["Close the vacuum line and the back vents, open the water, and start filling. Let the perlite soak for a moment.", "Crack the tank drain for a few seconds while it fills. Dirt settles at the bottom of every tank, and that short flush gets it out instead of mixing it into fresh media."]}, {"dur": 20, "shot": "install:group vent", "layout": "left", "h": "Purge ALL the air at the vents", "p": ["This is where customers get in trouble. Do not stop when water passes the window. Keep filling until water comes out of the vents, every one of them.", "Trapped air causes vibration, and vibration knocks perlite off the tubes. You will lose a little perlite out the vent, and that is fine. A bad precoat is not."]}, {"dur": 14, "shot": "sp55:precoat", "layout": "right", "h": "Precoat, and bump again if it is uneven", "p": ["Close the vents, press Next, and the system precoats. Watch the sight glass clear and the tubes appear in the window.", "After a media change the first coat is sometimes patchy. Bump and precoat a second time before you walk away. If the first one looks good, you are done."]}, {"dur": 28, "shot": "sp55:mediachange", "layout": "bottom", "h": "The whole change, start to finish", "p": ["Close the influent, ten bumps, drain with the vents open, rinse until the drain runs clear, final drain, close the valves, vacuum in the full amount of Harborlite.", "Close the vacuum and vents, refill, crack the drain, fill until water comes out of every vent, then precoat. Bump and precoat again if the coat is uneven."]}, {"dur": 14, "shot": "sp55:bottom", "layout": "left", "h": "Where the spent media goes", "p": ["Perlite is inert and does not react with anything we know of, but local health codes vary. Some do not care, some will not let it into the drain.", "For those sites we have DE screens and separation tanks, or you run the drain to a surge pit. Ask before the inspector does."]}, {"dur": 16, "shot": "card", "layout": "center", "h": "Three things to remember", "p": ["Let the Drain and Rinse menu lead, bump ten times first, and rinse until the drain water is clear, two times minimum.", "Use the spout on the Harborlite bag, load the full nameplate amount rounded up, and never cut the bag open.", "Fill until water comes out of every vent before you precoat. Trapped air is the number one reason a fresh coat looks bad."]}], "quiz": [{"q": "You just bumped and the differential is still 11 psi. What does that tell you?", "options": ["The bump tire needs more air", "The media is spent and it is time for a change", "The effluent valve is stuck", "The precoat ran too long"], "answer": 1, "why": "A differential of 10 psi or more right after a bump is one of the two signs the perlite is loaded and needs replacing."}, {"q": "You press Vacuum On and nothing pulls at the hose. Most likely cause?", "options": ["The bag is too full", "The compressor is off", "A valve is still open so the tank cannot pull a vacuum", "The tank still has perlite in it"], "answer": 2, "why": "The whole tank has to be sealed to act as the vacuum. Close the pump discharge and the other valves, then open only the vacuum transfer line."}, {"q": "When should you stop filling after loading new media?", "options": ["When water passes the viewing window", "When the pump has run for 5 minutes", "When water comes out of every vent line", "When the sight glass turns white"], "answer": 2, "why": "Water at the vents means the air is out. Trapped air causes vibration that knocks perlite off the tubes and ruins the precoat."}, {"q": "The nameplate calls for 75 lb and you have 25 lb bags. What do you load?", "options": ["Two bags, since more causes bridging", "Three bags", "One bag and top up next week", "Half a bag per tube row"], "answer": 1, "why": "Load the full required amount rounded up to whole bags. More is fine, less leaves bare tube that coats with dirt and grease."}, {"q": "How do you get the hose into a Harborlite bag?", "options": ["Cut the bag down the middle", "Open the built-in spout and put the hose in", "Pour the bag into a bucket first", "Punch a hole in the corner"], "answer": 1, "why": "The bags have a spout for exactly this. Cutting the bag open spills perlite across the floor."}, {"q": "After two rinses the drain water still shows perlite. What now?", "options": ["Precoat anyway, two is the standard", "Rinse again until it runs clear", "Add a chemical clean to the rinse water", "Skip the final drain"], "answer": 1, "why": "Two is the recommendation, not the limit. Clear drain water is the goal, and heavily loaded filters can take 7, 8, or 10 rinses."}]}, {"id": "10", "slug": "cleaning", "title": "Tube Wash and ChemClean Express", "tagline": "Garden hose, not a pressure washer, rotate the sheet the right way, and a chemical soak after startup and every 3 to 6 months", "scenes": [{"dur": 12, "shot": "sp55:window", "layout": "center", "h": "Tube Wash and ChemClean Express", "p": ["This module covers washing the tube elements through the window, rotating the tube sheet without wearing the O-rings, putting the window back right, and running a ChemClean Express soak."]}, {"dur": 18, "shot": "sp55:tubes", "layout": "left", "h": "When to wash the tubes", "p": ["Spray the tubes down at a media change when you can. Do a full tube wash every so often, not every change. A seasonal lifeguard can manage that.", "On a new build, do one after the first run. New piping sends everything in it to the filter, and our filters clean really well, which is the problem. Big bare sections on the tubes also mean wash first."]}, {"dur": 18, "shot": "sp55:window", "layout": "right", "h": "Bump, drain, pull the window", "p": ["Bump the filter, drain the tank, then unbolt the window: cover, acrylic, gasket. The cover is carbon steel and heavy, around 30 lb on the bigger sizes.", "Leave one or two bolts in at the bottom. The cover hangs there instead of lying on the floor, and everything lines back up when you close it."]}, {"dur": 16, "shot": "sp55:tubewash", "layout": "left", "h": "Garden hose. Never a pressure washer.", "p": ["Spray the perlite off the tubes with a garden hose. A pressure washer breaks the braids of the tube element, and a torn tube does not hold a coat.", "If a 4,000 gpm filter full of grease forces your hand, a weak electric unit is the most I will allow. I would still rather you did not."]}, {"dur": 18, "shot": "sp55:tubesheet", "layout": "right", "h": "Rotate the sheet. Follow the sticker.", "p": ["Deflate the bump tire and the tube sheet turns on the lift shaft, so you can bring every tube around to the window. Turn it in the direction on the sticker.", "Turning it the wrong way wears down the lift shaft O-rings, and then you are replacing them years early. Seasonal operators do this constantly."]}, {"dur": 16, "shot": "sp55:head", "layout": "left", "h": "Rotation is also your O-ring check", "p": ["If the sheet spins with very little resistance, the O-rings are lubricated and in place. If you cannot turn it, or it fights you, the O-rings are dry or torn.", "That is the time to look at them, before the bump gets weak or water shows up at the quick exhaust."]}, {"dur": 14, "shot": "sp55:tubes", "layout": "right", "h": "Clean, not perfect", "p": ["Get the tubes as clean as you reasonably can. You do not need every speck of perlite off. On an SP-55 you will never reach every nook, so do your best and move on."]}, {"dur": 18, "shot": "sp55:window", "layout": "left", "h": "Gasket in the slot, 30 ft-lbs, alternate", "p": ["Reinstall the gasket seated in its slot first, then the acrylic, then the cover. If the gasket is not in the slot, you will find out when you fill the tank.", "Torque the bolts to about 30 ft-lbs in an alternating pattern, not once around the circle. Same for the bottom four."], "stats": [{"n": 30, "suffix": " ft-lbs", "label": "Window bolt torque"}]}, {"dur": 12, "shot": "sp55:window", "layout": "right", "h": "A lighter cover is coming", "p": ["We are working on a fiberglass window cover, and a hinged version with a handle so it never has to go on the floor. Until then, it is carbon steel. Lift with your legs."]}, {"dur": 18, "shot": "sp55:orbit", "layout": "left", "h": "ChemClean Express: after startup, then quarterly or so", "p": ["ChemClean Express, or any degreaser, takes the oil and grease off the tubes that a hose cannot. Do one right after initial startup, then every 3 to 6 months.", "Heavy body oil and suntan lotion pushes you toward 3 months. A lightly used indoor pool can go 6. If a tube wash does not fix a patchy coat, this is the next step."]}, {"dur": 16, "shot": "install:marks D14,D15", "layout": "right", "h": "Load it exactly like media", "p": ["Drain the tank, close the valves, and vacuum the powder in with the vacuum transfer unit, the same as a bag of perlite. Then refill the tank with water.", "Nothing comes apart. You are not taking the head off to do a chemical clean."]}, {"dur": 16, "shot": "card", "layout": "center", "h": "Soak five hours to overnight, never past 72", "p": ["Five hours is the minimum and overnight is ideal. Seventy-two hours is the longest I have seen it still working, and anywhere in that window is fine."], "stats": [{"n": 5, "suffix": " h", "label": "Minimum soak"}, {"n": 72, "suffix": " h", "label": "Maximum effective"}]}, {"dur": 20, "shot": "rmf12:closed", "layout": "left", "h": "Flex Clean does the bumping for you", "p": ["On the RMF12, Menu, then Flex Clean. It walks the valves step by step, then bumps and precoats on its own during the soak, about once an hour.", "On an older controller, just let it sit with the vent open so pressure does not build. If a Flex Clean bumps nonstop for 24 hours, the bump auto time in parameters 12 to 15 is set too low."]}, {"dur": 16, "shot": "install:marks D10", "layout": "right", "h": "Drain, rinse, recharge", "p": ["When the soak is done, drain it, rinse the tank, and load fresh media the same as a media change. The procedure is on pages 60 to 61 of the O&M.", "The support line can walk you through every step of this if you are standing in front of it without a manual."]}, {"dur": 18, "shot": "sp55:tubes", "layout": "left", "h": "Chemical attack on the tubes", "p": ["High chlorine, a strong acid, or a strong base going through the filter degrades the threads of the tube element. Under the microscope a new tube has clean, intact strands. An attacked one does not.", "If the braid is spread, torn, or chemically eaten, replace the tube. We would rather you get a good precoat than nurse a dead tube."]}, {"dur": 16, "shot": "sp55:tubes", "layout": "right", "h": "Clean tube, visible spring", "p": ["When a tube is clean you should see the stainless spring inside through the mesh. If you cannot after a wash, the tube is fouling.", "I have seen tubes last 25 years, and I have seen people kill them in one. They are warranted for 10."]}, {"dur": 16, "shot": "card", "layout": "center", "h": "Three things to remember", "p": ["Garden hose only, leave two bottom bolts in, and torque the window to 30 ft-lbs in an alternating pattern with the gasket seated in its slot.", "Rotate the tube sheet in the sticker direction with the tire deflated. If it is hard to turn, check the O-rings.", "ChemClean Express after startup and every 3 to 6 months: vacuum it in, soak 5 hours to overnight, never past 72, then drain, rinse, and recharge."]}], "quiz": [{"q": "What do you wash the tube elements with?", "options": ["A gas pressure washer on the fan tip", "A garden hose", "Compressed air from the bump line", "A wire brush and degreaser"], "answer": 1, "why": "A pressure washer breaks the braid of the tube element. A garden hose takes the perlite off without damaging the mesh."}, {"q": "The tube sheet is hard to rotate with the tire deflated. What does that tell you?", "options": ["The tire is still partly inflated", "The tubes are too heavy with perlite", "The lift shaft O-rings are dry or torn", "The sticker direction is wrong"], "answer": 2, "why": "The sheet should spin with little resistance. Resistance means the O-rings need lubrication or replacement."}, {"q": "How long should a ChemClean Express soak?", "options": ["30 minutes", "5 hours minimum, overnight ideal, 72 hours maximum", "Exactly 10 minutes like a precoat", "One full week"], "answer": 1, "why": "Five hours is the minimum to work, overnight is ideal, and 72 hours is the longest it stays effective."}, {"q": "How does ChemClean Express go into the tank?", "options": ["Through the head with the davit swung open", "Poured into the hair and lint strainer", "Vacuumed in with the vacuum transfer unit, same as perlite", "Mixed into the precoat sight glass"], "answer": 2, "why": "It loads exactly like media: drain, close the valves, vacuum the powder in, then refill. Nothing comes apart."}, {"q": "A brand new pool is on its first week of operation. What cleaning do you plan?", "options": ["Nothing until the 5-year service", "An early media change, tube wash, and ChemClean Express", "A head gasket replacement", "Replace the tube elements"], "answer": 1, "why": "New piping sends debris and oil to the filter, and the Defender catches all of it. Clean it after the first run before judging the precoat."}, {"q": "You cleaned a tube and still cannot see the spring inside. What is going on?", "options": ["That is normal on 48 in tubes", "The tube is fouling and may need replacing", "The spring has been removed", "The perlite grade is too coarse"], "answer": 1, "why": "A clean tube shows the stainless spring through the mesh. If it stays hidden after a wash, the tube is fouled."}]}, {"id": "11", "slug": "maintenance", "title": "Maintenance Intervals and Procedures", "tagline": "The 1, 5 and 10 year schedule, lowering the tube sheet safely, head removal and torque, seized parts, lining repair, and the water chemistry that keeps it all alive", "scenes": [{"dur": 12, "shot": "sp55:orbit", "layout": "center", "h": "Maintenance Intervals and Procedures", "p": ["This module covers the maintenance schedule and kits, how to lower the tube sheet without hurting anyone, head removal and torque, what to do with seized bolts, lining repair, and water chemistry."]}, {"dur": 24, "shot": "sp55:section", "layout": "center", "h": "The maintenance schedule", "p": ["The system has not changed much since 2003, so any Defender O&M will have this. Daily is a bump. Everything else builds up from there."], "table": {"head": ["Interval", "Scope"], "rows": [["Daily", "Bump, check the differential"], ["Each media change, 4 to 6 wk", "Rinse tubes, check window gasket and lining at openings"], ["3 to 6 months", "ChemClean Express"], ["1 year", "Inspect: bump fully deflates and inflates, no leaks or cracks, lining, flush gauge lines"], ["5 year", "Lift shaft and bushing O-rings, stop ring, Molykote, inspect felt gasket"], ["10 year", "Bump assembly, felt gasket, O-rings, inspect tube elements"]]}}, {"dur": 16, "shot": "card", "layout": "center", "h": "Kits for 1, 5 and 10 years", "p": ["We sell maintenance kits by model for each interval: O-rings for the lift shaft and bushing, Molykote, stop ring pliers, and a bump assembly if you want it.", "For a service department, I can send a stocking list of the small parts that actually get replaced: solenoid valves, O-rings, that kind of thing. Keep them on the truck."]}, {"dur": 16, "shot": "sp55:head", "layout": "left", "h": "Year one: look at everything", "p": ["The first year is just inspection. Watch the bump tire fully deflate and fully reinflate, look for cracks or leaks on the tank, and look at the lining.", "Flush the gauge and transducer lines while you are there. Perlite gets stuck in them, and at one outdoor site we found algae."]}, {"dur": 20, "shot": "sp55:head", "layout": "right", "h": "Year five: the O-rings", "p": ["The O-rings on the lift shaft and the bump bushing separate the water side of the tank from the air side. Normal operation consumes them.", "Five years is the recommendation, though I have seen them need replacing at 3 and last to 10. Water at the quick exhaust, a brown muffler, or a weak bump means do it now. Check the felt gasket at the same time."]}, {"dur": 16, "shot": "sp55:tubesheet", "layout": "left", "h": "Year ten: bump assembly, felt, tubes", "p": ["At ten years, look hard at the whole bump assembly and replace it if the tire is worn. The felt gasket gets replaced, the O-rings again, and inspect the tube elements for a tight braid.", "The bump assembly has been the same since 2003, so it is a like-for-like swap on any unit out there."]}, {"dur": 18, "shot": "sp55:head", "layout": "right", "h": "Six inches of open air under that nut", "p": ["From the inflated position down to the rests is about 6 in of nothing. I have seen people pull the top nut and watch the tube sheet drop that whole distance at once.", "On an SP-27 that is a loud noise. On an SP-55 with a stainless sheet and 2,000 tubes hanging off it, that is dangerous. Always use the Defender toolkit."], "stats": [{"n": 6, "suffix": " in", "label": "Free drop without the toolkit"}, {"n": 2000, "suffix": " tubes", "label": "Hanging on an SP-55 sheet"}]}, {"dur": 22, "shot": "sp55:head", "layout": "left", "h": "Lowering the tube sheet with the toolkit", "p": ["Remove the cap nut and washers on top of the bump assembly. Thread the toolkit all-thread into the top of the lift shaft, which is tapped for it. Now remove the heavy top nut.", "The U-bracket has a bearing so the all-thread spins freely. Walk the hex nuts down with a wrench and the sheet lowers slowly onto the rubber rests. They are welded to the tank and take the full weight.", "Pages 62 to 63 of the O&M. If the toolkit has gone missing, it is a U-bracket with a bearing and all-thread. Call us and we will tell you how to build one."]}, {"dur": 14, "shot": "sp55:tubesheet", "layout": "right", "h": "Very old units: the head comes off", "p": ["On the really old Defenders the lift shaft does not come up above the head when the sheet is lowered. For tube sheet work on those, open the head.", "On anything newer the shaft is accessible from the top, and most of this can be done without opening the tank."]}, {"dur": 20, "shot": "sp55:head", "layout": "left", "h": "Head removal: davit and bottle jack", "p": ["Each head bolt has two washers, a lock ring, and a nut, all the way around the circumference. Unbolt, then lift with the bottle jack and swing the head on the davit, a full 360°.", "This is why we ask for 16 in above the tank, because the bump assembly rises with the head. On an SP-55 the far side will tilt down a little, and it is still fully supported.", "The bottle jack ships greased. If the unit sat for a couple of years, check it before you lean on it."]}, {"dur": 18, "shot": "card", "layout": "center", "h": "Two-stage torque, same order both passes", "p": ["Reassemble with the bolt sequence for that head size from the O&M. Stage one, every bolt to 20 ft-lbs in order. Stage two, the same order again to 45 ft-lbs.", "The bigger heads can go to about 70 ft-lbs, but that is system dependent. Going in order keeps the bolts you tightened first from loosening as you go around."], "stats": [{"n": 20, "suffix": " ft-lbs", "label": "Stage one"}, {"n": 45, "suffix": " ft-lbs", "label": "Stage two"}, {"n": 70, "suffix": " ft-lbs", "label": "Larger heads, about"}]}, {"dur": 18, "shot": "sp55:head", "layout": "right", "h": "New head gasket every time", "p": ["Replace the head gasket every time you open the head. It is not the end of the world if an undamaged one goes back once, but open and close it a few times and it will leak.", "We send it as a length, the same material for the 41, 49, and 55. Cut to size, glue the ends, and seat it in the channel. A 45° cut joins best, but a straight cut works."]}, {"dur": 18, "shot": "sp55:tubesheet", "layout": "left", "h": "The felt gasket and the stack order", "p": ["With the head off you are looking at the hold-down plate, the lift shaft, and the outer ring of felt. Look for an indent in that felt ring, which is the lip of the head pressing on it. No indent, no seal.", "Reassembly order matters: tube sheet, felt gasket, tubes dropped through, hold-down plate, then bolt it down. Out of order it still runs, but you will see media bypass."]}, {"dur": 20, "shot": "sp55:tubesheet", "layout": "right", "h": "Go easy on the tube sheet bolts", "p": ["About 15 bolts at 30 ft-lbs hold the stack together. After years in the tank, less is more: lubricant, a little heat, low torque. Strip one and you are drilling it out or replacing the tube sheet.", "Legoland ran a Defender 12 years with no service. The Delrin bump bushing had seized to the shaft and had to be drilled and chipped out. That is what skipping the five-year O-rings looks like."]}, {"dur": 14, "shot": "sp55:head", "layout": "left", "h": "Molykote: generous, and only two places", "p": ["When the O-rings go back in, coat them generously with Molykote. It is NSF rated and potable safe, and nobody is coming back to relube for years. More, not less.", "It goes on the O-rings and the bump bushing. Nothing else in the system needs it."]}, {"dur": 20, "shot": "sp55:tubes", "layout": "right", "h": "When a tube element gets replaced", "p": ["Replace a tube when the spring is no longer visible after cleaning, or the braid is spread, torn, or chemically attacked. The last number in the model is your maximum tube count. Usually a handful go, not all of them.", "We only supply 48 in tubes now. On a very old unit with a slatted downcomer, long tubes can catch on the slats, so tell us what diffuser you have before you order.", "Older tubes swelled and fought you on the way back in. The current ones swell less and the tube sheet holes were opened up. Tube elements are warranted for 10 years."]}, {"dur": 20, "shot": "sp55:section", "layout": "left", "h": "Lining repair: grind, two coats, gloves", "p": ["The Flexcel 3000 lining chips like powder coat if you hit it. Watch the head flange and the window opening, where people bang the cover and the hose. Fix chips before rust gets under them.", "The repair kit comes in quart containers with a rust inhibitor. Grind the spot to bare metal. Two coats, 24 hours between them, 12 at a minimum.", "The two parts get hot when they mix, hotter in a humid room. Wear gloves. The lining is warranted 10 years and I have seen it go 20 plus."]}, {"dur": 18, "shot": "install:group effluent", "layout": "right", "h": "Chlorine after the filter, 5 ppm continuous", "p": ["Dose chlorine and acid after the filter, after everything, so it is never going straight into the Defender. We want 5 ppm continuous at most and no more than 25 ppm in any 24 hours.", "A health department superchlorination is fine. Running at that level constantly attacks the tube elements and the felt gasket. Balanced water is what this system likes."], "stats": [{"n": 5, "suffix": " ppm", "label": "Continuous chlorine max"}, {"n": 25, "suffix": " ppm", "label": "Max in 24 hours"}]}, {"dur": 20, "shot": "card", "layout": "center", "h": "Flocculants, enzymes, and strange water", "p": ["Phosphate removers, flocculants, anything that binds: dose them as far from the filter as you can so they react in the pool first. In the filter they clump the perlite into patches, and it takes multiple tube washes and chem cleans to get it out.", "Enzymes have generally been fine as long as there is no binding agent. Ask us case by case.", "Unusual water, like the Teflon site in Ohio, coats tubes and seizes valve shafts. Tell us what is in the water and we will spec the right components."]}, {"dur": 16, "shot": "card", "layout": "center", "h": "Three things to remember", "p": ["Daily bump, O-rings and felt at five years, bump assembly and tubes at ten, and kits exist for all of it.", "Never pull the top nut without the toolkit, torque heads 20 then 45 in order, and replace the head gasket every time.", "Low torque, lube, and heat on old bolts, Molykote on the O-rings and bushing only, and keep chlorine, floc, and acid out of the filter."]}], "quiz": [{"q": "What happens if you remove the top nut on the lift shaft without the Defender toolkit?", "options": ["The bump tire deflates", "The tube sheet drops about 6 in onto the rests at once", "The head lifts off the tank", "Nothing, the snap ring holds it"], "answer": 1, "why": "There is about 6 in of open air between the raised position and the rests. On an SP-55 with 2,000 tubes that free drop is dangerous."}, {"q": "What is the head bolt torque sequence?", "options": ["45 ft-lbs once around", "20 ft-lbs in order, then 45 ft-lbs in the same order", "70 ft-lbs on every head", "Hand tight plus a quarter turn"], "answer": 1, "why": "Two stages in the same order so earlier bolts do not loosen as you go around. Larger heads can go to about 70 ft-lbs."}, {"q": "You open the head to inspect the felt gasket. What do you do with the head gasket?", "options": ["Reuse it if it looks fine", "Replace it every time the head is opened", "Only replace it at the 10-year service", "Glue the old one back in with more adhesive"], "answer": 1, "why": "Repeated opening wears the head gasket out. Cut a new length, join the ends, 45° is best, and seat it in the channel."}, {"q": "Where does Molykote go?", "options": ["On every bolt in the tank", "On the tube elements before precoat", "On the O-rings and the bump bushing only", "On the head gasket"], "answer": 2, "why": "Molykote is for the moving seals: the lift shaft and bushing O-rings and the bushing. Nothing else needs it."}, {"q": "A pool operator wants to add a phosphate remover. What do you tell them?", "options": ["Dose it right at the filter influent so it works fast", "Dose it as far from the filter as possible so it reacts in the pool first", "Add it to the precoat loop", "It is fine anywhere, perlite is inert"], "answer": 1, "why": "Binding agents clump perlite into patches inside the filter and take multiple washes and chem cleans to remove."}, {"q": "What is the chlorine limit for water going through the Defender?", "options": ["1 ppm at all times", "5 ppm continuous, no more than 25 ppm in 24 hours", "10 ppm continuous", "No limit, the lining is inert"], "answer": 1, "why": "Short superchlorination is fine, but continuous high chlorine attacks the tube elements and the felt gasket."}]}, {"id": "12", "slug": "troubleshooting", "title": "Troubleshooting, Warranty and Support", "tagline": "Symptom to cause by theme, what the warranty actually covers, and how to reach us 24/7 by call, text, email, and logs", "scenes": [{"dur": 12, "shot": "rmf12:closed", "layout": "center", "h": "Troubleshooting, Warranty and Support", "p": ["This module takes the troubleshooting table one theme at a time: precoat and media, bump and air, valves, controls and the drive, readings and drains. Then the warranty, and every way to get help."]}, {"dur": 24, "shot": "sp55:tubes", "layout": "center", "h": "Precoat and media problems", "p": ["Most precoat complaints come back to dirty tubes, air, or spent media. Work the list in order before you call."], "table": {"head": ["Symptom", "Likely cause and fix"], "rows": [["Patchy coat, bare sections", "Tube wash, then ChemClean Express on new builds, then fresh media. Then check air, precoat speed, media quantity"], ["Bubbles or gaps in the cake", "Air or turbulence. Purge at the vents. Air from the bump tire means bump O-rings"], ["Media back to the pool", "Felt gasket first, then media grade, precoat speed, damaged tube"], ["High DP right after a bump", "Media is spent. Change it and tube wash"], ["Media life under 3 weeks", "Sizing and flow rate, strainer, media grade and quantity, bather load. Send logs"]]}}, {"dur": 18, "shot": "sp55:tubesheet", "layout": "left", "h": "Media to the pool: felt gasket first", "p": ["The felt gasket seals every tube and the edge of the sheet against the lip of the head. It gets consumed, and chlorine and heat degrade it. If perlite reaches the pool, check it before anything else.", "Then the grade, finer than Harborlite 700 goes through the mesh, then precoat speed too high pushing media through, then a torn tube. We have a media-to-pool checklist. Ask for it."]}, {"dur": 22, "shot": "sp55:head", "layout": "center", "h": "Bump and air", "p": ["The bump is one tire, one quick exhaust, and two O-rings. Almost every bump complaint is one of those or the air feeding them."], "table": {"head": ["Symptom", "Likely cause and fix"], "rows": [["Weak bump, tire not deflating", "Clogged muffler on the quick exhaust: unscrew it and run louder. Then worn or dry O-rings, low air, bent lift shaft on a new install"], ["Water or rust at the quick exhaust", "Lift shaft or bushing O-rings torn. Replace before returning to service"], ["Brown or black muffler", "Same thing. Water is getting to the air side"], ["Compressor running constantly", "Pneumatic leak. Soapy water on every line and fitting. They can be tiny"], ["Tire will not deflate at all", "Look for a quick exhaust. Some sites plumb straight into the tire"]]}}, {"dur": 18, "shot": "install:marks D7,D8", "layout": "right", "h": "A valve that slams", "p": ["A valve that bangs open or shut during precoat and water hammers the room is an actuator adjustment, not a failure. Needle valves on the actuator set the speed: counterclockwise faster, clockwise slower, by feel with air applied.", "The silver set screws are the travel stops. Check they have not been bumped or vibrated past 90°. Debris in a needle valve is the usual cause on a system that was fine two years ago."]}, {"dur": 20, "shot": "rmf12:part plc", "layout": "left", "h": "A dead valve: start at the PLC", "p": ["Outputs 0, 1, and 2 on the main PLC are your solenoids, and the LED should light when the controller calls the valve. No LED, the controller is not asking. Use I/O Diagnostics to call it yourself.", "LED on for the effluent valve and nothing happens downstream? That is buildup on the PLC contactor. Call us for a replacement PLC."]}, {"dur": 20, "shot": "rmf12:part manifold", "layout": "right", "h": "Then the solenoid, the air, the actuator", "p": ["The solenoid has its own LED. If it lights, press the blue test button underneath with a pen. A whoosh of air means the solenoid is fine.", "Then follow the air: cracked tubing, a loose fitting, enough pressure. Then the travel stops.", "If all that is good and the actuator still will not move, unbolt it at the flange and turn the stem with a wrench. If the valve moves, replace the actuator. They carry a 3 or 5 year warranty."]}, {"dur": 22, "shot": "rmf12:closed", "layout": "center", "h": "Controls and the drive", "p": ["The number one support call this year, out of about 2,000, is the RMF12 and VFD setup. Most of it is one switch, one jumper, or one parameter."], "table": {"head": ["Symptom", "Likely cause and fix"], "rows": [["Main pump offline alarm", "No run confirm from the VFD. Check the VFD is on and the B24+ and T17 wiring to relay 1"], ["VFD not reading flow", "Analog/digital switch behind the Danfoss keypad, meter output jumper, wiring to 54, 4 to 20 mA scaling"], ["Frozen HMI", "Cycle power. If it keeps happening, we replace it"], ["Stuck on the desktop at boot", "Reset the internal breaker. Then a software reload on a Siemens SD card"], ["Flex Clean bumping nonstop", "Bump auto time set too low, parameters 12 to 15. Reset to about once an hour"]]}}, {"dur": 16, "shot": "rmf12:terminals T-17,B-24+", "layout": "left", "h": "Main pump offline, about 5 seconds in", "p": ["The RMF12 waits about 5 seconds after start for run confirm on T17 and B24+. If it never comes, you get the alarm and nothing else will run.", "If the motor really is running and the drive just cannot send the signal, a jumper between T17 and B24+ clears it. Fix the wiring properly afterward."]}, {"dur": 20, "shot": "sp55:window", "layout": "center", "h": "Readings and drains", "p": ["The gauges and the transducers tee off the same taps, so they should agree. When they do not, the tap is the suspect, not the sensor."], "table": {"head": ["Symptom", "Likely cause and fix"], "rows": [["Odd pressure readings", "Perlite, or algae on an outdoor site, in the gauge and transducer lines. Disconnect the tees, flush, reconnect"], ["Tank drains slowly", "Sediment at the bottom of the tank. Crack the drain regularly during media changes"], ["No vacuum at the hose", "Junction box wiring, and every other valve closed so the tank can pull a vacuum"], ["Air pressure alarm near 100 psi", "RMF12 sensor reads 0 to 100. Set the regulator to 85"]]}}, {"dur": 18, "shot": "sp55:section", "layout": "center", "h": "Three things that solve most calls", "p": ["The perlite is the filter. The tubes are the framework. When water quality drops, think media first, tubes second, hardware last.", "Differential pressure is your indicator. Read it after a bump, not during one.", "Always compare it with flow and a look through the window. A pressure number by itself lies. Pressure plus flow plus a visual almost never does."]}, {"dur": 22, "shot": "sp55:orbit", "layout": "center", "h": "What the warranty covers", "p": ["Everything runs from the ship date, not the startup date. Project contracts can change these, so check with your sales director or with us."], "table": {"head": ["Item", "Typical warranty from ship date"], "rows": [["Tank and lining", "10 years"], ["Tube elements", "10 years"], ["Valve actuators", "3 or 5 years"], ["RMF12 controller", "1 to 3 years, project dependent"], ["O-rings, felt gaskets, consumables", "1 to 3 years"]]}}, {"dur": 18, "shot": "card", "layout": "center", "h": "Components, not labor. Bring the serial number.", "p": ["Warranty generally covers the part, not the labor, though we do work with teams on it. The serial number on the stainless pad gets you the ship month and year, the project, and the warranty status in one call.", "If a unit sat on site for two years and something arrived damaged, run the startup checklist and tell us. Tank damage we look into before we replace, because we want to know what went wrong.", "Service partners can come to us directly. Parts can ship to you, a distributor, or the site. Every project is a unique zebra."]}, {"dur": 22, "shot": "rmf12:closed", "layout": "left", "h": "Call or text 866-722-1776, any hour", "p": ["Our AI tech support line is 866-722-1776, call or text, 24 hours a day. It knows the O&Ms, the commissioning guides, and the parameters. Ask it which parameter to change and it gives you the number and the setting.", "It has walked a customer through a frozen HMI and converted Danfoss terminals to an ABB drive over the phone. If it cannot solve it, it sends an urgent message to the engineers and we call you back.", "Need to get in front of the panel? Ask it to call back in 15 minutes and it picks up where you left off."]}, {"dur": 18, "shot": "card", "layout": "center", "h": "Email, tickets, and photos", "p": ["Email is nbts@xyleminc.atlassian.net. Long address, I know. Every call, text, or email opens a ticket, so when I pick up I already know what you have tried.", "Send photos by text or email and they attach to the ticket. Tell us the site and the serial number up front and we hit the ground running."]}, {"dur": 18, "shot": "rmf12:part hmi", "layout": "right", "h": "The O&M on the door, the logs behind it", "p": ["Every RMF12 panel carries a QR code to the O&M, and tech support will be on there too. Any Defender O&M covers most of the system, because the system has not changed much.", "For a problem nobody can see, pull the SD card behind the HMI, copy the zip, and send it. We run a full diagnostic report and solve a lot of issues remotely."]}, {"dur": 20, "shot": "card", "layout": "center", "h": "What is coming, and how to reach me", "p": ["A partner portal is about a month out: exploded views of every major product, SAP part numbers, FAQs, maintenance steps, and direct parts orders and warranty requests, so nothing sits in a voicemail.", "The media change, tube wash, cycle, and wiring animations, the commissioning guides, and the error code list all go out to attendees. Maintenance kits for 1, 5, and 10 years are on the e-commerce site.", "And me directly: casey.glynn@xylem.com. We are 500 companies in a trench coat. If the trench coat is slow, push me."]}, {"dur": 16, "shot": "card", "layout": "center", "h": "Three things to remember", "p": ["Media to the pool is the felt gasket until proven otherwise, a weak bump is the muffler or the O-rings, and a dead valve is PLC LED, solenoid LED, test button, air, stops, actuator, in that order.", "Warranty runs from ship date, covers components not labor, and starts with the serial number on the stainless pad.", "866-722-1776 by call or text, nbts@xyleminc.atlassian.net, photos to the ticket, and the SD card zip when nobody on site can see the problem."]}], "quiz": [{"q": "Perlite is showing up in the pool. What do you check first?", "options": ["The precoat timer", "The felt gasket", "The flow meter direction", "The compressor pressure"], "answer": 1, "why": "The felt gasket seals every tube and the sheet edge. It gets consumed over time, so it is the first stop for media bypass."}, {"q": "The bump tire will not deflate. Quickest first check?", "options": ["Replace the bump assembly", "Unscrew the muffler on the quick exhaust", "Lower the regulator to 50 psi", "Change parameter 45"], "answer": 1, "why": "A clogged muffler traps the air in the tire. Remove it, the bump gets louder, and you are running until a new one arrives."}, {"q": "The effluent valve PLC LED is on, the solenoid LED is off, and nothing moves. Where is the problem?", "options": ["The actuator needle valves", "The travel stops", "The PLC contactor", "The felt gasket"], "answer": 2, "why": "When the PLC thinks it is sending the output but the solenoid never sees it, that is buildup on the PLC contactor. Call for a replacement PLC."}, {"q": "The compressor never shuts off. What do you do?", "options": ["Set the regulator to 120 psi", "Soapy water test every pneumatic line and fitting", "Add a second compressor", "Increase bumps to 20"], "answer": 1, "why": "A compressor that runs constantly is feeding a leak. They can be tiny, and soapy water is the fastest way to find them."}, {"q": "A three-month-old actuator will not move even with air and the stem turns freely by wrench. What now?", "options": ["Replace the valve body", "Run the system manually", "Call support, it is a warranty actuator replacement", "Flip the air lines"], "answer": 2, "why": "If the valve moves by hand and the actuator will not, the actuator has failed. They carry a 3 or 5 year warranty."}, {"q": "It is 11 pm and the engineers are not answering. Fastest route to help?", "options": ["Email the sales director", "Call or text 866-722-1776", "Wait until morning", "Post on the partner portal"], "answer": 1, "why": "The AI support line runs 24/7, opens a ticket, and escalates to an engineer callback if it cannot solve the issue."}]}];
